const resultProfiles=[{"code": "ACTG", "strength": "思い立ったらすぐ動き出し、周りを巻き込んで初動の流れをつくる力。", "gd": ["ファシリテーター"], "actions": ["「とりあえずやってみた」経験を1つ選び、きっかけ・動いた内容・結果を、自己PRの下書きとして書き出す。"]}, {"code": "ACTP", "strength": "困っている人の様子に気づいて声をかけ、自然に人の輪を広げていく力。", "gd": ["ファシリテーター"], "actions": ["ガクチカの候補を1つ選び、「誰のどんな困りごとに気づいたか」を1文で書き出す。"]}, {"code": "ACIG", "strength": "自分で目標を決め、未知のテーマを試しながら可能性を広げる力。", "gd": ["発表者"], "actions": ["気になる職種の求人票を1つ開き、仕事内容の中から「これなら自分で試して形にできそう」と思うものを1つ選んで、そう思う理由を1行で書く。"]}, {"code": "ACIP", "strength": "気になったことにすぐ飛び込み、自分の体験を言葉にして人に届ける力。", "gd": ["発表者"], "actions": ["自分のSNSやブログから、就活で見せられる投稿を3つ選び、届いた人数や反応を書き出す。"]}, {"code": "ASTG", "strength": "決まった目標にすぐ取りかかり、周囲の役割を整えて着実に進める力。", "gd": ["タイムキーパー"], "actions": ["友達にGD練習を1回頼んで日程を決め、当日は「時間割の提案」を自分から引き受ける。"]}, {"code": "ASTP", "strength": "困りごとの兆しを早めに察して、決まった手順の中で素早く手を打てる力。", "gd": ["書記"], "actions": ["模擬面接で聞かれそうな「人の役に立った経験」の答えを、声に出して1回話してみる。"]}, {"code": "ASIG", "strength": "自分の作業の型を持ち、毎回同じ手順で素早く仕上げる力。", "gd": ["タイムキーパー"], "actions": ["志望職種で求められる資格や技能を1つ調べ、取得にかかる期間と、今の自分との差を書き出す。"]}, {"code": "ASIP", "strength": "一人で任された仕事を、期限と約束を守って確実にやり切る力。", "gd": ["書記"], "actions": ["一人でやり切った仕事を1つ選び、応えるまでの時間と、再び頼まれた回数を、ESに書ける形に整える。"]}, {"code": "DCTG", "strength": "高い目標から逆算して道筋を描き、メンバーの力を束ねて成果へ運ぶ力。", "gd": ["ファシリテーター"], "actions": ["気になる業界の企業を3社選び、採用ページの事業内容を1行ずつ書いて、3社の違いを一言で比べる。"]}, {"code": "DCTP", "strength": "課題の背景を読み解き、立場の違う人をまとめて、変化に向かう道筋を描く力。", "gd": ["ファシリテーター"], "actions": ["気になる社会課題を1つ選び、その解決に取り組む企業や団体を3つ探して、リストにする。"]}, {"code": "DCIG", "strength": "疑問を見つけたら、根拠を集めて納得するまで掘り下げる力。", "gd": ["書記"], "actions": ["ゼミや研究のテーマを、難しい言葉を避けて、友達へ1分で説明してみる。"]}, {"code": "DCIP", "strength": "日常の小さな違和感から問いを立て、まだない形を考え抜く力。", "gd": ["発表者"], "actions": ["「社会のここが変だ」と感じたことを1つ選び、志望動機の「きっかけ」として3文で書く。"]}, {"code": "DSTG", "strength": "準備と確認を重ね、周りが迷わず動ける土台をつくる力。", "gd": ["タイムキーパー"], "actions": ["提出済みのESを1通開き、志望動機に具体例・期間・成果が入っているかを確認して直す。"]}, {"code": "DSTP", "strength": "相手の話を最後まで受け止め、安心して頼れる関係を長くつくれる力。", "gd": ["書記"], "actions": ["友達に面接官役を頼み、「人の話を聞いた経験」を2分で話す練習を1回する。"]}, {"code": "DSIG", "strength": "一つの領域に長く集中し、知識と技術を確実に深める力。", "gd": ["書記"], "actions": ["志望する専門職の募集要項を1つ開き、求められる資格・経験と、自分の積み上げを照らし合わせる。"]}, {"code": "DSIP", "strength": "人に知られなくても、必要なことを淡々と続けて、大切なものを保ち続ける力。", "gd": ["書記"], "actions": ["続けていることを1つ選び、始めた時期・続けた年数・保たれた状態を、ガクチカとして書き出す。"]}];
const importedGuidance={"ACTG": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "場に火をつけ、人を巻き込んで動かす人。"}, {"label": "このタイプの特徴", "text": "あなたが入ると、その場の温度が少し上がります。本人は意識していなくても、「とりあえずやってみよう」という一言で、固まっていた空気が動き出した経験が何度もあるはずです。初対面の相手ともいつの間にか打ち解けていて、「顔が広いよね」と言われることも多いでしょう。誰かと一緒に何かをやり遂げた瞬間、「これだ」と体の奥から力が湧く感覚を、あなたは知っています。"}, {"label": "代表的な強み", "text": "初速の速さ、人を自然と巻き込む明るさ、場に溶け込むのが早い対人スキル。計画が完璧でなくても、まず動いて形にしながら整えていける人です。"}, {"label": "力が発揮される場面", "text": "前例のない企画、立ち上げ直後で役割が決まっていないチーム、人を集める必要があるイベントや新規開拓。「誰かが最初の一歩を出さないと始まらない」場面で、真価を発揮します。"}, {"label": "他タイプと異なる特徴", "text": "一人で突っ走る挑戦者でも、周りに合わせるだけの協調型でもなく、「走りながら仲間を乗せる」ことができる点。スピードとチーム力を同時に持つ人は、実はそう多くありません。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "始める力が強いぶん、仕上げの粘りが課題。"}, {"label": "このタイプの特徴", "text": "始めるのは得意なのに、気づけば机の引き出しに「途中でやめたこと」が何個も眠っていませんか。新しいことが始まる瞬間のワクワクが一番強くて、軌道に乗ると少し熱が冷めてしまう。周りには見せないけれど、「自分は飽きっぽいのかも」と密かに気にしているところがあるはずです。また、じっくり一人で考え込む時間が続くと、落ち着かなくて誰かに連絡したくなる。それは、あなたの影の部分（普段あまり使わない側）が「静かに考える・変わらないものを保つ」ことだからです。"}, {"label": "つまずきやすいこと", "text": "仕上げの粘りが続きにくい、細部の確認が後回しになる、勢いで引き受けて自分の首を絞める。"}, {"label": "力が発揮される場面", "text": "ESの推敲や企業研究のような静かな準備、数字の細かい確認、長く続くルーティン作業。"}, {"label": "弱みをカバーする方法", "text": "作業を30分単位に区切る、緻密な友人に最後のチェックを頼むなど、「一人でやり切らない仕組み」が合います。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "初対面のメンバーが集まった沈黙の数秒間、あなたは耐えられずに口を開いていませんか。「じゃあ、まず役割決めようか」「とりあえず意見出してみよう」と言った瞬間、場が一気に動き出す。あなたにとって、それは作戦というより、ほぼ反射です。ただ、盛り上がるほど話す量が増えて、あとから「しゃべりすぎたかも」と反省することもあるでしょう。"}, {"label": "向いている役割", "text": "ファシリテーター（司会）。書記や時間管理のように、支える役割で力を出す人もいます。"}, {"label": "自然にできる立ち回り", "text": "口火を切る、沈黙を破る、発言の少ない人に「どう思う？」と振る。場を温めることが自然にできます。"}, {"label": "評価されやすいポイント", "text": "議論を前に進める推進力と、メンバーを巻き込む姿勢。「この人がいると議論が止まらない」と見られます。"}, {"label": "やりすぎると逆効果になる行動", "text": "自分の案で押し切る、話しすぎて他の人の発言時間を奪う、時間配分を忘れて盛り上がる。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "毎日同じことの繰り返しだと、あなたは3か月くらいで「このままでいいのかな」と考え始めるはずです。逆に、任された範囲が広くて、人を動かしながら何かを作っている最中は、疲れていても不思議と楽しい。「忙しいのに充実している」という状態が、あなたにとっての最高の職場です。ただ、そのぶん無理をしがちで、周りに「大丈夫そう」と思われて助けてもらえない場面もあるのではないでしょうか。"}, {"label": "活躍しやすいポジション", "text": "アクセルを踏む推進役。緻密な参謀タイプがそばにいると、力が何倍にもなります。"}, {"label": "組織の中で担いやすい役割", "text": "プロジェクトのリーダー、新規事業の立ち上げメンバー、チームのムードメーカー。"}, {"label": "目指しやすいキャリア", "text": "法人営業から営業マネージャーへ、新規事業開発、事業責任者、将来的な起業。"}, {"label": "特徴を活かした未来像", "text": "30代で新しい事業の旗振り役として、ゼロから仲間を集めてサービスを世に出している。会議室の端で、あなたの隣にはいつも、勢いを現実に変えてくれる信頼できる相棒がいます。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "「スピード感があるね」と褒められる裏で、あなたは何度か「ちょっと待って、聞いてない」と言われたことがありませんか。悪気はなく、ただ動いたほうが早いと思っただけ。でも、置いていかれた側は、別の気持ちを抱えています。意見がぶつかったときも、あなたは数分で気持ちを切り替えられるのに、相手は何日も引きずっている。そのズレに、あとから気づくことがあるはずです。"}, {"label": "強みが裏目に出るパターン", "text": "スピードを優先して根回しや合意形成を飛ばし、後から反発される。"}, {"label": "人間関係で気をつけること", "text": "熱量の差を「やる気がない」と受け取らないこと。慎重な人は反対しているのではなく、リスクを見てくれている人です。"}, {"label": "チームで働く際の注意点", "text": "役割分担を明確にして、自分がすべての中心にならないようにする。"}, {"label": "意思決定のクセ", "text": "「面白そう」で即決しがち。決める前に「最悪の場合どうなるか」を一つだけ考えると、失敗が減ります。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "探す", "text": "今月中に、新規事業や立ち上げの経験がある社会人1人に、OB・OG訪問を申し込む（大学のキャリアセンター、ゼミの先輩、OB・OG訪問サービスで探す）。"}, {"label": "聞く", "text": "当日は、「立ち上げの最初の1か月で何から着手したか」「思うように進まなかった場面と、どう立て直したか」「周りを巻き込むときに最初にやったこと」の3つを聞く。"}, {"label": "使う", "text": "聞いた内容のうち、自分の「とりあえずやってみた」経験と重なる点を1つ選び、ESのガクチカに書き足す。"}, {"label": "伸ばしたいこと", "items": ["数字で計画を立てる力（簡単な予算・KPIの管理）", "最後までやり切る習慣と、人の話をさえぎらず聴く力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、説明会で「この会社、面白そう」と盛り上がっては、翌週には別の会社に心が移っていませんか。ESは勢いで書けるのに、見直しの段階で飽きてしまい、提出ギリギリになることも多いはずです。面接では不思議と話が盛り上がるのに、あとから「あれ、結局何を伝えたんだっけ」と振り返ることもあるでしょう。"}, {"label": "企業選びのポイント", "text": "社名の勢いや雰囲気で選ばない。「若手に裁量がある」は、入社何年目で何を任されたかの具体例で確認する。"}, {"label": "面接で強みを伝えるには", "text": "「行動力があります」ではなく「〇人を巻き込み、△の成果を出した」と人数や数字で語る。"}, {"label": "自己PRで気をつけること", "text": "強みが「行動力」なら、弱みは「慎重さに欠けること」と裏表にしておくと一貫性が出る。エピソードを盛りすぎない。"}, {"label": "適性検査での傾向", "text": "活動意欲や達成意欲が高く、慎重性は低めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["新しい挑戦をした若手社員の実例を3つ以上言えるか", "配属後2〜3年の仕事内容を具体的にイメージできるか", "地道な業務の割合を把握したうえで納得しているか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "決まった手順を淡々とこなす日が続くと、あなたは自分でも気づかないうちに元気がなくなっていくはずです。反対に、「今月の目標、みんなでどう超えるか」という話し合いに入っているときは、目の輝きが変わる。人が動き、数字が動き、会社が変わっていく手応えのある環境が、あなたにはいちばん居心地がいいのです。"}, {"label": "相性の良い業界の例", "text": "ITベンチャー、人材、広告・PR、イベント・エンタメ、実行支援型のコンサル。"}, {"label": "相性の良い職種の例", "text": "法人営業、企画職、新規事業開発、プロジェクトマネージャー。"}, {"label": "活躍しやすい会社の特徴", "text": "若手の抜擢が多い、成果が評価に直結する、チームで目標を追う文化がある。"}, {"label": "ミスマッチになりやすい環境", "text": "年功序列が強い、承認フローが長い、一人で黙々とルーティンをこなす職場。"}, {"label": "このタイプに合いやすい理由", "text": "即応（A）と挑戦（C）で変化の多い環境を楽しめ、協働（T）で人を動かす力が活き、自己実現（G）の成長欲求が成果主義の環境で満たされるからです。キャリアアンカーでは、起業家的創造性と経営管理の要素が強い傾向です。"}]}], "ACTP": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "人の困りごとに気づき、仲間を動かせる人。"}, {"label": "このタイプの特徴", "text": "あなたの「これ、おかしくない？」という一言は、不思議と周りの人を動かします。理屈で説得しているわけではなく、本気で気にしている空気が伝わるからです。気づけば周りに協力者が集まっていて、「あなたが言うなら手伝うよ」と言われた経験が、一度や二度ではないはずです。誰かの表情が明るくなる瞬間が、あなたにとって何よりの栄養になっています。"}, {"label": "代表的な強み", "text": "共感を呼ぶ語りかけの力、課題を見つけたらすぐ動く実行力、仲間を集める人柄。"}, {"label": "力が発揮される場面", "text": "ボランティアや地域活動の立ち上げ、社会課題をテーマにしたコンテスト、サークルや団体を新しい方向に動かす場面。"}, {"label": "他タイプと異なる特徴", "text": "想いを語れるだけでなく、動いて形にできる点。理念と行動と仲間の三つを同時に持つ人は、組織にとって大きな推進力になります。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "頼まれると断れず、自分の限界に気づきにくい。"}, {"label": "このタイプの特徴", "text": "頼まれると、心の中では「ちょっときついな」と思っていても、口では「いいよ、やるよ」と言ってしまう。気づけば自分の予定が人のために埋まっていて、「自分のやりたいことって何だっけ」と立ち止まる夜があるはずです。また、自分の成果を数字や言葉で説明するのが苦手で、「頑張ったのに、うまく伝わらなかった」と悔しい思いをした経験もあるでしょう。あなたの影の部分（普段あまり使わない側）は、数字で冷静に見積もること、そして自分の都合を優先することです。"}, {"label": "つまずきやすいこと", "text": "断れずに抱え込む、理想が先行して現実の見積もりが後回しになる、自分の頑張りを伝えるのが苦手。"}, {"label": "力が発揮される場面", "text": "「その施策の費用対効果は？」と問われる面接、利益を優先する判断を求められる場面、自己PR。"}, {"label": "弱みをカバーする方法", "text": "活動を「誰が・何人・どれくらい助かったか」で数字にする、週に1日は活動しない日をつくる。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDで議論が「効率」や「売上」の話に傾いたとき、あなたは心の中で「でも、それって誰のためなんだろう」と引っかかっていませんか。その違和感を口にした瞬間、議論の空気が変わった経験があるはずです。発言の少ない人の表情にも気づいて、「〇〇さんはどう思う？」と自然に振っている。そのときのあなたは、評価を気にしているというより、ただ場を良くしたいだけです。"}, {"label": "向いている役割", "text": "ファシリテーター（司会）。"}, {"label": "自然にできる立ち回り", "text": "「そもそも誰のための議論か」を最初に確認する、発言の少ない人の意見を拾って場を温める。"}, {"label": "評価されやすいポイント", "text": "目的意識の高さ、ユーザーや相手の視点に立った発言、チームの一体感づくり。"}, {"label": "やりすぎると逆効果になる行動", "text": "理想論で議論を引っ張って現実的な結論から離れる、反対意見に感情的に反応する。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "数字だけを追う仕事を続けると、あなたは少しずつ心が乾いていくはずです。逆に、自分の仕事の先に誰かの笑顔や「ありがとう」が見えると、多少きつくても踏ん張れる。肩書や給料よりも、「この仕事に意味がある」と思えるかどうかが、あなたの原動力です。ただ、意味を感じられないと一気に気持ちが離れてしまう、という繊細さも持っています。"}, {"label": "活躍しやすいポジション", "text": "ビジョンを掲げて人を動かす旗振り役。数字に強い仲間と組むと、実現力が一気に上がります。"}, {"label": "組織の中で担いやすい役割", "text": "プロジェクトのリーダー、社内外の協働をつなぐハブ、CSR・サステナビリティの推進役。"}, {"label": "目指しやすいキャリア", "text": "ソーシャルビジネスの企画、地方創生の推進、官民連携の事業開発、社会起業家。"}, {"label": "特徴を活かした未来像", "text": "地域や業界の課題を、企業・行政・住民を巻き込んで解決する「つなぎ役のリーダー」として名前が知られている。「あの人に相談すれば道が開ける」と言われる存在です。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "「良いことをしているんだから」という気持ちが強いとき、あなたは周りの反応が薄いことに、内心傷ついているのではありませんか。協力してくれない人を責めたいわけではないのに、心のどこかで「どうして一緒にやってくれないんだろう」と思ってしまう。その気持ちを隠して笑顔でいるぶん、ある日突然どっと疲れが出ることもあるでしょう。"}, {"label": "強みが裏目に出るパターン", "text": "「良いことだから」と準備不足のまま始めて、関係者を振り回してしまう。"}, {"label": "人間関係で気をつけること", "text": "熱量の低い人を責めない。関わり方は人それぞれで、小さな協力も大切な力です。"}, {"label": "チームで働く際の注意点", "text": "一人で背負わず、仕事を任せる。任せることは、相手の成長の機会を渡すことでもあります。"}, {"label": "意思決定のクセ", "text": "共感できるかどうかで判断しがち。「続けられる仕組みか」も同じ重さで確認する。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "探す", "text": "今月中に、志望する会社や業界が関わる地域イベント・ボランティア・体験企画を1つ見つけて、参加を申し込む。"}, {"label": "聞く", "text": "運営スタッフに、「現場で一番困ること」「参加者から出る声で多いもの」「それをどう仕事にしているか」を聞く。"}, {"label": "使う", "text": "現場で見た困りごとを1つ選び、「誰のどんな困りごとか」を1文にして、志望動機のネタにする。"}, {"label": "伸ばしたいこと", "items": ["収支や事業性を考える基礎的な数字感覚", "自分を休ませるセルフマネジメント力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、企業のホームページで「社会課題の解決」という言葉を見るたびに心が動き、気づけばどの会社も素敵に見えてしまっていませんか。面接では熱い想いを語れるのに、「それで、あなた自身は何をしたの？」と聞かれた瞬間、少し言葉に詰まる。そんな経験があるなら、あなたの強みは想いそのものではなく、そこから動いた「行動」にあります。"}, {"label": "企業選びのポイント", "text": "「社会貢献」を掲げる企業でも、実際の仕事は営業や事務が中心のことがある。配属後に何をするかまで確認する。"}, {"label": "面接で強みを伝えるには", "text": "「人の役に立ちたい」で終わらせず、「〇〇の課題に対して△人を巻き込み、□を実現した」と行動と結果で語る。"}, {"label": "自己PRで気をつけること", "text": "社会貢献したいという想いだけでは評価されにくい。結論、行動、成果、学びの順で短くまとめ、強みが「巻き込み力」なら弱みは「抱え込みやすさ」と裏表にする。"}, {"label": "適性検査での傾向", "text": "社会関係の面で協調的、意欲の面で活動性が高く出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["その会社の事業が「誰の、どんな困りごと」を解決しているか一文で言えるか", "社会貢献と利益がどう両立しているか説明できるか", "若手が企画や提案に関われる具体例を知っているか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "社内の誰もが「うちの会社は何のためにあるのか」を自分の言葉で話せる職場にいると、あなたは自然と力が湧いてくるはずです。反対に、ミッションが額縁に飾られているだけで、現場は数字の話しかしない職場では、少しずつ心が冷めていく。「ここにいる意味」を感じられるかどうかが、あなたにとっては給料以上に大きな条件です。"}, {"label": "相性の良い業界の例", "text": "ソーシャルベンチャー、教育、医療・ヘルスケア系スタートアップ、地方創生・まちづくり、インフラ系の新規事業部門。"}, {"label": "相性の良い職種の例", "text": "企画職、事業開発、コミュニティマネージャー、広報・PR、課題解決型の法人営業。"}, {"label": "活躍しやすい会社の特徴", "text": "ミッションが明確で、社員が自分の言葉で語れる。部署を越えた協働が多い。"}, {"label": "ミスマッチになりやすい環境", "text": "利益だけが評価軸、指示通りに動くことが求められる、顧客の顔が見えない仕事。"}, {"label": "このタイプに合いやすい理由", "text": "即応（A）と挑戦（C）で新しい解決策をすぐ試せ、協働（T）で仲間を集められ、社会貢献（P）の想いがミッション型の組織でまっすぐ活きるからです。キャリアアンカーでは、奉仕・社会貢献に起業家的創造性が重なる傾向です。"}]}], "ACIG": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "決めて動く速さで、一人でも道を開ける人。"}, {"label": "このタイプの特徴", "text": "決めるのが早い。これは、あなたが思っている以上に大きな武器です。周りが「どうしよう」と迷っている間に、あなたはすでに一歩目を踏み出していて、うまくいかなければ次の手を打っている。失敗しても引きずらず、「じゃあ次」と切り替えられる。その軽やかさに、実は密かに憧れている人が周りにいるはずです。"}, {"label": "代表的な強み", "text": "決断の速さ、自走力、リスクを恐れない挑戦心、結果へのこだわり。指示がなくても動け、一度決めたらやり抜く力があります。"}, {"label": "力が発揮される場面", "text": "個人目標を追う営業、独学でのスキル習得、個人で始めたプロジェクト（発信・開発・副業）、状況が見えない中で最初の一手を打つ場面。"}, {"label": "他タイプと異なる特徴", "text": "誰かを待たずに一人で始められる「着手の速さ」と、自己完結力。0から1を作る最初の一歩を踏み出せる人は貴重です。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "一人で抱えて、周りへの共有が後回しになりやすい。"}, {"label": "このタイプの特徴", "text": "実は、人に頼るのが苦手というより、「頼んだ結果、自分の思い通りに進まないこと」が苦手ではありませんか。だから「自分でやったほうが早い」と思ってしまい、結果として一人で抱える。報告や相談が少なくなって、「何をしているのかわからない」と思われていることにも、薄々気づいているはずです。強気に見えて、本当は「認められたい」という気持ちが人一倍強い。その気持ちを、あまり表に出さないだけです。影の部分（普段あまり使わない側）は、周囲に預けること、そして立ち止まってじっくり考えることです。"}, {"label": "つまずきやすいこと", "text": "報告・連絡・相談が少なくなる、興味が移ると前のことを放置する、自分のやり方に固執する。"}, {"label": "力が発揮される場面", "text": "チーム課題、上司の承認が必要な仕事、長期間同じ作業が続く業務、協調性を見られるGD。"}, {"label": "弱みをカバーする方法", "text": "始める前に一言共有する、途中経過も見せる。信頼できる相談相手を一人つくる。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDでみんなが無難な意見を出し合っているとき、あなたは「それ、他のグループも言いそう」と心の中でつぶやいていませんか。自分だけは違う切り口を出したくなって、気づけば発言してしまう。その発言が刺さって場が動くこともあれば、「あれ、浮いたかも」と焦ることもある。どちらの経験も、きっとあるはずです。"}, {"label": "向いている役割", "text": "発表者（独自の切り口を出し、結論を言葉にして伝える役）。"}, {"label": "自然にできる立ち回り", "text": "誰も思いつかない切り口を出す、行き詰まった議論に新しい方向を示す、結論が出たら聞き手に伝わる順番で発表する。"}, {"label": "評価されやすいポイント", "text": "独自の視点、発想の速さ、結論を一度で伝える力。"}, {"label": "やりすぎると逆効果になる行動", "text": "他者の案を否定して自分の案を通そうとする、合意を待たずに結論を出す。GDは協調性も見られていると意識を。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "「やり方は任せる、結果だけ見せて」と言われる環境に、あなたは心底ほっとするはずです。逆に、毎日の報告や細かいチェックが多い職場では、息が詰まって力が出ない。給料や安定よりも、「自分の裁量でどこまでやれるか」が、あなたの働く意味に直結しています。時々、誰にも言えない孤独を感じることがあっても、それも含めて自分の道だと思っているのではないでしょうか。"}, {"label": "活躍しやすいポジション", "text": "裁量を任されて突破口を開く切り込み隊長。調整役が後ろにいると力が最大になります。"}, {"label": "組織の中で担いやすい役割", "text": "新市場の開拓担当、個人目標型のプレイヤー、社内ベンチャーの発起人。"}, {"label": "目指しやすいキャリア", "text": "トップセールス、スペシャリスト職、フリーランス、起業家、スタートアップの創業メンバー。"}, {"label": "特徴を活かした未来像", "text": "20代のうちに「この分野ならこの人」と言われる実績をつくり、30代で自分の看板や事業を持って自由に働いている。自分のペースと責任で人生を組み立てている姿が似合います。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "結果を出しているのに、なぜか周りとの距離が少しずつ開いていく。そんな感覚に、心当たりはありませんか。あなたは悪気なく動いているのに、周りからは「勝手に決める人」と見られてしまう。そして、その誤解を解くのが面倒で、そのままにしてしまう。ときどき「どうせわかってもらえない」と思う瞬間が、あなたの中にあるかもしれません。"}, {"label": "強みが裏目に出るパターン", "text": "独断で動いて周囲の信頼を失う、組織のルールを軽く見て評価を下げる。"}, {"label": "人間関係で気をつけること", "text": "「自分でやったほうが早い」が口癖になると孤立しやすい。感謝や共有を言葉にするだけで関係は大きく変わります。"}, {"label": "チームで働く際の注意点", "text": "自分の担当範囲と期限を明確にして、進捗を見える化する。"}, {"label": "意思決定のクセ", "text": "直感で即決し、後から修正に追われがち。大きな決断は一晩寝かせるだけで精度が上がります。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "探す", "text": "手を動かすタイプのインターン（企画・開発・分析など）を2つ探して、今月中に申し込む（企業の採用ページ、就活サイトのインターン欄）。"}, {"label": "残す", "text": "参加中は、成果物ごとに「仮説→実行→結果」を1行ずつメモに残す。"}, {"label": "使う", "text": "終わったら、成果物を1枚にまとめ、応募先ごとに見せる順番を変えて整理する。"}, {"label": "伸ばしたいこと", "items": ["人に頼る力、協力を引き出す力", "一つのことを半年以上続ける継続力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、周りが業界研究や筆記対策の話をしている間に、「自分は自分のやり方でいく」と、一人で別のことを進めていませんか。それがうまくいくこともあれば、情報を取りこぼして焦ることもある。面接では自信がにじみ出る反面、「この人、組織に馴染めるかな」と見られる不安を、心の片隅に抱えているはずです。"}, {"label": "企業選びのポイント", "text": "「裁量がある」と言っても、若手のうちは決裁権が少ない会社も多い。実際に任される範囲を確認する。"}, {"label": "面接で強みを伝えるには", "text": "「自分で考え、動き、〇〇を達成した」と主体性と成果を数字で示し、周囲とどう連携したかも一言添える。"}, {"label": "自己PRで気をつけること", "text": "強みが「主体性」なら、弱みは「周囲への共有不足」と裏表にして、改善している行動を添える。"}, {"label": "適性検査での傾向", "text": "自己尊重や達成意欲が高く、従順性は低めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["入社1〜3年目で個人に任される仕事の範囲を知っているか", "評価が成果ベースか年次ベースかを確認したか", "副業や社内起業などの制度があるか調べたか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "あなたが一番いきいきするのは、「誰が何をやったか」がはっきり見える環境ではないでしょうか。頑張りが平均化されて、年次で横並びに評価される職場では、頑張るほど虚しくなる。逆に、結果を出せば出すほど任される範囲が広がる環境では、疲れていても顔が輝いています。"}, {"label": "相性の良い業界の例", "text": "スタートアップ全般、IT・Web、不動産・金融などのインセンティブ型営業、クリエイティブ業界。"}, {"label": "相性の良い職種の例", "text": "個人目標型の営業、エンジニア、マーケター、デザイナー、新規事業担当。"}, {"label": "活躍しやすい会社の特徴", "text": "成果主義、働き方の自由度が高い、少人数で一人の担当範囲が広い。"}, {"label": "ミスマッチになりやすい環境", "text": "細かいマニュアルや承認が多い、横並び評価、チームワークが最優先で個人の成果が見えにくい職場。"}, {"label": "このタイプに合いやすい理由", "text": "即応（A）と挑戦（C）で未知のことに素早く飛び込め、独立（I）で自分のやり方を貫け、自己実現（G）の成長欲求が成果主義の環境で報われるからです。キャリアアンカーでは、自律・独立と起業家的創造性が強い傾向です。"}]}], "ACIP": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "現場に飛び込み、行動で説得力をつくる人。"}, {"label": "このタイプの特徴", "text": "あなたは、資料やニュースを見るだけでは満足できず、「実際に自分の目で見たい」と思ってしまいます。現場に足を運び、当事者の話を聞いた後は、もう「知らなかったこと」にはできない。その当事者意識の強さが、言葉や行動に説得力を与え、気づけば周りから「あの人が言うなら」と一目置かれているはずです。"}, {"label": "代表的な強み", "text": "当事者意識の強さ、現場に飛び込むフットワーク、前例にとらわれない発想、一人でも始める覚悟。"}, {"label": "力が発揮される場面", "text": "海外ボランティアや地域のフィールドワーク、制度のすき間にある課題への対応、個人で始めた支援活動や発信。"}, {"label": "他タイプと異なる特徴", "text": "誰かがやるのを待たない社会派。最初は一人でも、その行動が後から仲間を呼び込む力を持っています。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "頑張りすぎて、自分の生活や体調が後回しになる。"}, {"label": "このタイプの特徴", "text": "頑張りすぎて、自分の体調や生活が後回しになっていませんか。「自分より大変な人がいるから」と、疲れていても弱音を飲み込んでしまう。助けを求めるのが苦手で、本当は誰かに「大丈夫？」と聞いてほしい夜があっても、その一言を自分から言えない。また、組織の手続きや承認の遅さにいら立ち、「その間にも困っている人がいるのに」と感じることもあるはずです。影の部分（普段あまり使わない側）は、じっくり待つこと、チームに預けること、効率や利益を優先することです。"}, {"label": "つまずきやすいこと", "text": "一人で抱え込んで助けを求めにくい、組織の手続きにいら立つ、活動を続ける仕組みづくりが後回しになる。"}, {"label": "力が発揮される場面", "text": "大組織の稟議や調整、チームで役割分担して進める業務、利益優先の意思決定。"}, {"label": "弱みをカバーする方法", "text": "活動を記録して共有し、他の人が引き継げる形にする。組織のルールを「活動を長く続けるための道具」と捉え直す。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "議論が「効率的な案」や「儲かる案」に偏ってきたとき、あなたは「でも、それで困る人はいないかな」と、ふと引っかかってしまいませんか。その一言を言うかどうか迷って、タイミングを逃して後悔した経験が、一度はあるはずです。逆に言えた日は、場の空気が少し変わって、ちゃんと自分の仕事をした気持ちになる。"}, {"label": "向いている役割", "text": "発表者（現場の具体例や問題提起を、結論の発表に生かす役）。"}, {"label": "自然にできる立ち回り", "text": "「現場ではこうなっている」と具体的な視点を持ち込む、見落とされがちな当事者の存在を指摘する、発表では具体例を使って結論を伝える。"}, {"label": "評価されやすいポイント", "text": "視点の独自性、当事者目線、議論を本質に戻す一言。"}, {"label": "やりすぎると逆効果になる行動", "text": "自分の経験を唯一の正解として押しつける、まとめの段階で新しい論点を出し続ける。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "デスクに座って資料を作るだけの日が続くと、あなたは「自分は何のためにここにいるんだろう」と考え始めるはずです。逆に、現場の空気を感じながら、目の前の人に直接役立てている実感があるときは、体は疲れていても心は満ちている。立派な肩書きよりも、「あの人のおかげで助かった」という一言のほうが、あなたにとってはずっと価値があります。"}, {"label": "活躍しやすいポジション", "text": "最前線で動き、課題を発見して持ち帰る探索役。仕組み化が得意な人と組むと成果が広がります。"}, {"label": "組織の中で担いやすい役割", "text": "新規地域・新市場の開拓、フィールド調査、社会課題型プロジェクトの発起人。"}, {"label": "目指しやすいキャリア", "text": "国際協力・開発の専門職、社会起業家、地域おこし系の事業者、ジャーナリスト、医療・福祉分野の改革者。"}, {"label": "特徴を活かした未来像", "text": "海外や地方の現場で自ら課題を見つけ、小さな事業を立ち上げ、それが「新しい当たり前」として広がっていく。気づけば、あなたの背中を見て動き出した人が周りにたくさんいます。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "使命感が強いぶん、周りが同じ温度で動いてくれないと、孤独を感じやすいのではありませんか。「どうしてみんな、見て見ぬふりができるんだろう」と思った経験もあるでしょう。その気持ちは間違っていないけれど、口に出すと壁ができてしまう。だから黙って一人で動いて、また孤独が深まる。そんな循環に、心当たりがあるかもしれません。"}, {"label": "強みが裏目に出るパターン", "text": "使命感が強すぎて周囲を置き去りにする、自分の健康や生活を後回しにする。"}, {"label": "人間関係で気をつけること", "text": "組織の中の人を「わかっていない」と見下さない。制度をつくる側にも理由があります。"}, {"label": "チームで働く際の注意点", "text": "単独行動の前に目的を共有して、応援してもらえる状態をつくる。"}, {"label": "意思決定のクセ", "text": "「今すぐ助けたい」で動きがち。続けられるか（資金・体力・人）を確認してから始めると、長く支えられます。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "見る", "text": "志望企業の公式SNSと広報の発信を、1週間続けて見る。"}, {"label": "考える", "text": "反応が多かった投稿を3つ選び、「なぜ反応が多いのか」を自分なりの仮説にする。"}, {"label": "聞く・使う", "text": "広報担当が出る座談会で、その仮説を1つ質問する。答えを、自己PR（発信で人の行動を変えた経験）と結びつける。"}, {"label": "伸ばしたいこと", "items": ["事業として回す基礎知識（お金の流れ・資金調達）", "語学や専門スキルなど、現場で通用する武器"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、「会社に入る」という選択自体に、少し引っかかりを感じていませんか。「組織に入らなくても、自分で動けばいいのでは」という考えが、頭の片隅にあるはずです。面接で「なぜうちなのか」と聞かれて、本音と建前の間で言葉を探す。そんな場面が多いのではないでしょうか。"}, {"label": "企業選びのポイント", "text": "現場に出られるのは何年目からか、海外・地方配属の実態はどうかを確認する。"}, {"label": "面接で強みを伝えるには", "text": "「自ら〇〇の現場に行き、△という課題を見つけ、□を実行した」と、行動の起点と結果を明確にする。"}, {"label": "自己PRで気をつけること", "text": "独立心が強いと「すぐ辞めそう」と見られやすいので、「この会社で学びたいこと」を具体的に。強みが「当事者意識」なら、弱みは「一人で抱え込みやすいこと」と裏表にする。"}, {"label": "適性検査での傾向", "text": "意欲や自己尊重が高く、従順性や回避性は低めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["現場に関われる職種・配属の割合を確認したか", "社会的意義だけでなく、自分がその会社で得たいスキルを言えるか", "個人の提案が採用された事例を知っているか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "現場を知らない人が机の上で決めたルールに従うだけの職場では、あなたは少しずつ表情が硬くなっていくはずです。反対に、現場の声がそのまま意思決定に届く環境では、遠慮なく意見を言え、疲れていても顔が明るい。「現場に近い」「顔の見える相手がいる」という条件は、あなたにとって譲れないポイントです。"}, {"label": "相性の良い業界の例", "text": "国際協力・開発コンサル、NPO・NGO、医療・福祉、農業・地方創生、報道・メディア、ソーシャルスタートアップ。"}, {"label": "相性の良い職種の例", "text": "フィールド調査・事業開発、記者、地域コーディネーター、海外駐在を含む営業・プロジェクト職。"}, {"label": "活躍しやすい会社の特徴", "text": "現場の裁量が大きい、少人数で一人の担当範囲が広い、社会的ミッションが事業の中心にある。"}, {"label": "ミスマッチになりやすい環境", "text": "本社での管理業務が中心、意思決定が遅い大組織、社会との接点を感じにくい仕事。"}, {"label": "このタイプに合いやすい理由", "text": "即応（A）と挑戦（C）で未知の現場に飛び込め、独立（I）で自分の判断で動け、社会貢献（P）の使命感が課題解決の最前線で満たされるからです。キャリアアンカーでは、奉仕・社会貢献と自律・独立が強い傾向です。"}]}], "ASTG": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "状況を読んで動き、現場を安定して回せる人。"}, {"label": "このタイプの特徴", "text": "あなたは、忙しい現場で急にトラブルが起きても、慌てず「まず何からやるか」を切り替えられる人です。目立つ活躍をしているつもりはなくても、あなたがいない日に限ってなぜか現場が回らなくなり、周りが初めて存在の大きさに気づく。そんな経験が、一度や二度ではないはずです。「いつも通り」を安定して続けられることの価値を、あなたは自分で思っているよりずっと高く評価されています。"}, {"label": "代表的な強み", "text": "臨機応変な対応力、確実にやり遂げる実行力、チームの中での安定感、経験を積むほど伸びる成長力。"}, {"label": "力が発揮される場面", "text": "アルバイトのリーダー、部活やサークルの運営、店舗や現場でのトラブル対応、決まった目標をチームで追う仕事。"}, {"label": "他タイプと異なる特徴", "text": "動きは速いのに無茶はしないバランス感覚。スピードと安定感を兼ね備え、「任せて安心」と思われる存在です。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "周りに合わせるぶん、自分の希望が後回しになる。"}, {"label": "このタイプの特徴", "text": "「どうしたい？」と聞かれると、一瞬言葉に詰まってしまう。周りの希望には敏感なのに、自分の希望は後回しにしてきたせいで、答えがすぐ出てこないのです。また、毎日が目の前のことで埋まっていて、気づけば「3年後の自分」を考える余裕がない。それをなんとなく不安に思いながらも、日々の忙しさに紛れて先送りしている。影の部分（普段あまり使わない側）は、先を読んでじっくり考えること、そして自分の意見を前に出すことです。"}, {"label": "つまずきやすいこと", "text": "前例のない挑戦に尻込みしやすい、目の前の対応に追われて長い目で見た計画が後回しになる、周囲に合わせすぎて意見を言わない。"}, {"label": "力が発揮される場面", "text": "「あなたならではの考えは？」と問われる面接、ゼロから企画を考える課題、正解のない議論。"}, {"label": "弱みをカバーする方法", "text": "日々の仕事に「改善点を一つ提案する」習慣を持つ、半年後と1年後の目標を書いておく。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDが始まると、あなたはまず「時間配分、どうしますか？」と無意識に言っていませんか。誰も頼んでいないのに、議事メモを取り始め、話が脱線しかけたら「戻しましょうか」とさりげなく軌道修正している。終わったあと、「自分の意見、あんまり言えなかったな」と少し後悔するのも、あなたの定番です。"}, {"label": "向いている役割", "text": "タイムキーパー。"}, {"label": "自然にできる立ち回り", "text": "時間配分を提案して進行を整える、出た意見を整理して見える化する、議論が脱線したら軌道修正する。"}, {"label": "評価されやすいポイント", "text": "チームへの貢献意識、安定した進行サポート、現実的な提案。"}, {"label": "やりすぎると逆効果になる行動", "text": "裏方に徹しすぎて自分の意見を一度も言わない、時間管理にこだわって議論の質を下げる。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "方針が毎週のように変わる職場では、あなたは表面上は適応しているように見えても、内心かなり消耗しているはずです。逆に、役割や目標が明確で、チームで協力しながら一歩ずつ成果が積み上がる環境では、驚くほど安定して力を出せる。派手な成功よりも、「去年より確実に成長している」という実感が、あなたにとっての大きなやりがいです。"}, {"label": "活躍しやすいポジション", "text": "チームの実行部隊の中心。ビジョンを描くリーダーの右腕として最も力を発揮します。"}, {"label": "組織の中で担いやすい役割", "text": "現場リーダー、新人教育担当、チーム内の調整役。"}, {"label": "目指しやすいキャリア", "text": "営業・店舗運営からチームリーダー、マネージャーへ。現場をよく知る管理職やスーパーバイザー。"}, {"label": "特徴を活かした未来像", "text": "経験を積み重ね、30代で「現場もわかる信頼されるマネージャー」として大きなチームを任されている。派手ではなくても、確かな積み上げの先に、人が自然と集まる場所をつくっています。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "「いい人」と言われることが、少しだけ複雑ではありませんか。感謝されるのは嬉しいけれど、「いい人」で終わってしまうと、本当に評価されたい部分は見てもらえていない気がする。かといって、自分から「もっと評価してほしい」とは言いにくい。その飲み込んだ言葉が、少しずつ積もっているのではないでしょうか。"}, {"label": "強みが裏目に出るパターン", "text": "対応力が高いぶん仕事が集まり、いつのまにか便利屋になっている。"}, {"label": "人間関係で気をつけること", "text": "周りに合わせすぎてストレスをためない。違和感は早めに、小さく伝える。"}, {"label": "チームで働く際の注意点", "text": "自分の担当以外まで手を出しすぎない。「頼られること」と「抱え込むこと」を区別する。"}, {"label": "意思決定のクセ", "text": "「いつものやり方」を選びがち。たまに新しい選択肢も並べて比べてみる。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "探す", "text": "次に参加する説明会か社員座談会で、質問を2つ用意する（リーダー役の1日の流れ、進行役やリーダーを任される時期）。"}, {"label": "聞く", "text": "答えを、「入社何年目で・どんな規模のチームを・どんな目標で任されるか」の3点でメモする。"}, {"label": "使う", "text": "複数社で同じ質問をして、リーダーを任される時期と内容を表に並べ、志望順位の材料にする。"}, {"label": "伸ばしたいこと", "items": ["自分の意見を論理的に伝える力", "長期目標を立てて逆算する計画力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、周りの友達の進み具合を気にして、「自分もそろそろ動かなきゃ」と焦りながら、実際には目の前の予定をこなすので精一杯になっていませんか。志望動機を考えようとすると、「自分が何をしたいか」より先に、「どんな会社なら周りに納得してもらえるか」を考えてしまう。その癖が、面接での「あなたらしさ」を弱くしてしまうことがあります。"}, {"label": "企業選びのポイント", "text": "安定性だけで選ぶと、入社後に刺激が足りなく感じることがある。研修制度やキャリアステップの具体性を確認する。"}, {"label": "面接で強みを伝えるには", "text": "「チームのために〇〇の状況で素早く対応し、△の結果につなげた」と、対応力と成果をセットで語る。"}, {"label": "自己PRで気をつけること", "text": "「サポートが得意」だけだと主体性が弱く見える。自分から動いた場面を必ず入れ、強みが「対応力」なら弱みは「自分の意見を後回しにしやすいこと」と裏表にする。"}, {"label": "適性検査での傾向", "text": "持続性や従順性が高く出やすく、独自性は控えめに出る傾向。"}, {"label": "企業選びのチェックポイント", "items": ["入社後3年・5年のキャリアステップを説明できるか", "研修・OJTの具体的な内容を確認したか", "チームで目標を追う仕事か、個人ノルマ中心かを把握したか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "社員同士の距離が近く、困ったときは自然と誰かが助けてくれる。そんな空気の職場に入ると、あなたは驚くほど早く馴染んで、気づけば中心メンバーになっているはずです。反対に、成果を個人で競わされる環境や、教えてもらえないまま放り出される職場では、「自分が悪いのかも」と責めてしまいやすい。環境との相性が、あなたの調子を大きく左右します。"}, {"label": "相性の良い業界の例", "text": "大手メーカー、商社、小売・流通、ホテル・旅行、金融（銀行・保険）、物流。"}, {"label": "相性の良い職種の例", "text": "法人営業（ルート営業）、店舗運営・エリアマネージャー、営業事務、生産管理、カスタマーサクセス。"}, {"label": "活躍しやすい会社の特徴", "text": "教育制度が整っている、評価基準が明確、チームで目標を追う文化、着実に昇進できる仕組みがある。"}, {"label": "ミスマッチになりやすい環境", "text": "方針が頻繁に変わるベンチャー、個人プレー中心、教育がなく放任の職場。"}, {"label": "このタイプに合いやすい理由", "text": "即応（A）で現場の変化にすばやく対応でき、安定（S）の環境で実力を着実に積み上げられ、協働（T）でチームに貢献しながら自己実現（G）の成長を実感できるからです。キャリアアンカーでは、保障・安定と経営管理の要素が重なる傾向です。"}]}], "ASTP": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "人の変化に気づき、先回りして支えられる人。"}, {"label": "このタイプの特徴", "text": "友達や同僚が、なぜかあなたにだけは悩みを打ち明ける。そんな経験が何度もあるはずです。あなたは相手の話を遮らず、否定せず、ただ受け止めてくれる。その安心感は、意識して身につけたものではなく、あなたが自然に持っている才能です。人が困っているときに「何か手伝おうか」と動ける人は、実はそう多くありません。"}, {"label": "代表的な強み", "text": "気配り、即座のフォロー、協調性、責任感。相手に「この人がいてくれてよかった」と思わせる安心感があります。"}, {"label": "力が発揮される場面", "text": "接客・サービス業のアルバイト、イベントの受付や運営、困っている仲間のサポート、緊急時の対応。"}, {"label": "他タイプと異なる特徴", "text": "言われる前に動ける優しさ。相手の状況を察してすぐ手を差し伸べる力は、どんな組織でも大切にされます。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "断れず抱え込み、自分の気持ちが置き去りになる。"}, {"label": "このタイプの特徴", "text": "「ノー」と言うとき、あなたは断ること自体より、「相手にどう思われるか」で頭がいっぱいになっていませんか。引き受けたあとで「やっぱり無理だった」と一人で後悔し、でも断る勇気はまた出せない。また、人の悩みを聞きすぎて、自分のことのように疲れてしまう日もあるはず。「自分の気持ちは後でいいや」を繰り返しているうちに、自分が何を感じているのかわからなくなることもあります。影の部分（普段あまり使わない側）は、自分の希望を前に出すこと、そして新しい挑戦に先頭で飛び込むことです。"}, {"label": "つまずきやすいこと", "text": "断れずに仕事を抱える、自分の意見を後回しにする、変化の大きい環境で疲れやすい、自己アピールが苦手。"}, {"label": "力が発揮される場面", "text": "自己PRや逆質問のように「自分」を語る場面、競争の激しい環境、方針がころころ変わる職場。"}, {"label": "弱みをカバーする方法", "text": "できること・できないことを事前に伝える、自分の貢献を数字や相手の反応で記録しておく。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDで誰かの発言が少ないと、あなたはそわそわして、「〇〇さんはどう思いますか？」と声をかけたくなりませんか。意見がぶつかりかけると、空気が悪くなるのが耐えられなくて、場を和らげる一言を探している。ただその結果、自分の意見を言うタイミングを逃し、終わってから「あれも言えばよかった」と反省するのが、あなたの定番です。"}, {"label": "向いている役割", "text": "書記（意見を整理し、発言の少ない人の意見も拾う役）。"}, {"label": "自然にできる立ち回り", "text": "発言できていない人に話を振る、出た意見をわかりやすく整理する、対立しそうなときに和らげる一言を入れる。"}, {"label": "評価されやすいポイント", "text": "チーム全体への配慮、傾聴力、議論を円滑にする貢献。"}, {"label": "やりすぎると逆効果になる行動", "text": "気配りだけで自分の意見を出さない、全員の意見を尊重しすぎて結論が出ない。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "「ありがとう」の一言が、あなたの一日を決めてしまうことはありませんか。どんなに忙しくても、誰かに感謝された日は不思議と疲れが軽くなる。逆に、数字や成績だけで評価される環境では、自分の価値が見えなくなってしまう。人の役に立っている実感と、安心して働ける土台。その両方があるとき、あなたは最も長く、安定して力を出せます。"}, {"label": "活躍しやすいポジション", "text": "顧客やメンバーに最も近い最前線のサポート役。役割とルールが明確だと、安心して力を発揮できます。"}, {"label": "組織の中で担いやすい役割", "text": "チームの潤滑油、新人のフォロー役、顧客対応のプロフェッショナル。"}, {"label": "目指しやすいキャリア", "text": "医療・福祉の専門職、公務員、インフラ企業の総合職、カスタマーサポートのリーダー、人事（労務・研修）。"}, {"label": "特徴を活かした未来像", "text": "地域や会社の「なくてはならない存在」として、困ったときに真っ先に名前が挙がる人になっている。派手さはなくても、人の記憶に長く残る仕事をしています。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "「優しい人」として頼られるうちに、いつのまにか「断らない人」として扱われていないでしょうか。頼まれごとが増えるのに、自分の仕事は後回しになって、夜遅くに一人で片付けている。それでも誰にも言えないのは、頼んだ側に悪気がないことをわかっているからです。その優しさが、時々あなた自身を追い込んでいることに、薄々気づいているのではありませんか。"}, {"label": "強みが裏目に出るパターン", "text": "優しさから仕事を引き受けすぎて、キャパオーバーになる。"}, {"label": "人間関係で気をつけること", "text": "相手に合わせすぎて本音を言えず、不満をためこむ。小さな「ノー」を言う練習を。"}, {"label": "チームで働く際の注意点", "text": "フォローしすぎると、他のメンバーの成長機会を奪うことがある。"}, {"label": "意思決定のクセ", "text": "「みんなが困らない選択」を優先し、自分の希望を後回しにしがち。進路は自分軸で決める。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "見る", "text": "志望する会社の店舗・窓口・サービスを、客として1回利用する。スタッフの対応を、「声のかけ方」「困りごとへの先回り」「忙しいときの優先順位」の3点で観察して、メモする。"}, {"label": "聞く", "text": "次の座談会や説明会で、観察した場面を1つ挙げて、「あの対応は、どう教わっているのですか」と質問する。"}, {"label": "使う", "text": "聞いた答えを、自己PRの「先回りして動いた経験」と並べて、共通点を1つ書き出す。"}, {"label": "伸ばしたいこと", "items": ["断る力、優先順位をつける力", "自分の考えを論理的に伝えるプレゼン力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、友達の相談に乗っているうちに、自分のESが全然進んでいない、という状況になりがちではありませんか。面接では「周りを支えてきた」ことを話せるのに、「それで、あなた自身はどうしたいの？」と聞かれると、急に言葉が出なくなる。実はその質問が、一番自分と向き合うきっかけになる質問です。"}, {"label": "企業選びのポイント", "text": "「人の役に立てる」だけで選ばず、勤務時間・休日・異動などの働き方の安定性も確認する。"}, {"label": "面接で強みを伝えるには", "text": "「周りをよく見て、〇〇の状況で△のサポートをした結果、□になった」と、具体的な場面で語る。"}, {"label": "自己PRで気をつけること", "text": "謙遜しすぎない。「自分が動いたから変わったこと」を堂々と伝える。強みが「気配り」なら、弱みは「自分の意見を後回しにしやすいこと」と裏表にする。"}, {"label": "適性検査での傾向", "text": "従順性が高く、自責性（責任を感じやすい）も高めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["その仕事で「誰を、どう支えるのか」を具体的に言えるか", "残業・休日・転勤の実態を確認したか", "社員同士が助け合う文化があるか、雰囲気を自分の目で見たか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "社員同士が「お疲れさま」「ありがとう」を自然に言い合える職場にいると、あなたは驚くほど穏やかに力を出せるはずです。反対に、他人の失敗を指摘し合うような空気の職場では、直接責められていなくても、心が少しずつすり減っていく。仕事内容より、「どんな人たちと働くか」が、あなたにとっては大きな条件です。"}, {"label": "相性の良い業界の例", "text": "医療・福祉、インフラ（電力・ガス・鉄道）、公務員・団体職員、ホテル・航空、教育、生活協同組合。"}, {"label": "相性の良い職種の例", "text": "看護・介護などの専門職、窓口・カスタマーサポート、人事・総務、接客サービス職、事務職。"}, {"label": "活躍しやすい会社の特徴", "text": "社会的な役割が明確、チームワーク重視、役割やマニュアルが整っている、長く働ける制度がある。"}, {"label": "ミスマッチになりやすい環境", "text": "個人の成果を競い合う文化、ノルマが厳しい営業、方針が頻繁に変わる組織。"}, {"label": "このタイプに合いやすい理由", "text": "即応（A）で相手の変化にすぐ応えられ、安定（S）の環境で安心して力を出せ、協働（T）のチームの中で社会貢献（P）の想いを日々実感できるからです。キャリアアンカーでは、奉仕・社会貢献と保障・安定が中心になる傾向です。"}]}], "ASIG": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "速く正確に仕上げる、静かな職人タイプ。"}, {"label": "このタイプの特徴", "text": "締め切りが近づいても、あなたは慌てません。必要なことを淡々と処理して、気づけば提出済み。周りが焦っている横で、静かに終わらせている姿に、実は「すごいな」と思っている人が多いはずです。派手な言葉で自分を飾らなくても、積み上げた結果が語ってくれる。そんな職人気質が、あなたの核にあります。"}, {"label": "代表的な強み", "text": "処理の速さと正確さ、自己管理力、スキルを磨き続ける向上心、一人でも任せられる安定感。"}, {"label": "力が発揮される場面", "text": "資格や検定の勉強、決まった業務を効率よくこなすアルバイト、個人で担当を持つ仕事、トラブル時の冷静な一次対応。"}, {"label": "他タイプと異なる特徴", "text": "「速いのにミスが少ない」。手が早く、しかもルールを守って品質が安定している点が強みです。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "自分のやり方に寄りすぎて、頑張りが伝わりにくい。"}, {"label": "このタイプの特徴", "text": "実は、「自分のやり方で進めたい」気持ちが強くて、人の意見を取り入れるのに少し時間がかかりませんか。頭では「確かにそのほうがいいかも」と思っても、体が慣れた方法に戻ってしまう。また、自分の頑張りを他人に説明するのが面倒で、「見てればわかるでしょ」と思ってしまうこともある。でも、見ていない人には当然伝わらず、評価されないことにモヤモヤしたことがあるはずです。影の部分（普段あまり使わない側）は、周囲を巻き込むこと、そして未知のことに先頭で飛び込むことです。"}, {"label": "つまずきやすいこと", "text": "自分の領域の外に関心が向きにくい、大きな変化や新しい挑戦を避けがち、チームの輪に入るまでに時間がかかる。"}, {"label": "力が発揮される場面", "text": "初対面のチームで議論するGD、ゼロから企画を出す課題、方針が頻繁に変わる環境。"}, {"label": "弱みをカバーする方法", "text": "月に一つ「小さな新しいこと」に挑戦する、チームでは自分の得意分野を先に宣言して役割を取りにいく。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDで初対面の人たちと議論するのは、正直なところ少し苦手ではありませんか。最初の数分は様子を見て、「この人たちはどんな流れで進めたいのかな」と観察している。そして、議論が散らかり始めたあたりで、「一度整理しましょうか」と静かに切り出す。そのタイミングの良さは、あなたの強みですが、本人は「もっと早く言えばよかった」と思っているかもしれません。"}, {"label": "向いている役割", "text": "タイムキーパー。"}, {"label": "自然にできる立ち回り", "text": "時間内に結論を出すための段取りを示す、議論の要点を素早く正確に記録する、現実的な実行案を出す。"}, {"label": "評価されやすいポイント", "text": "進行の安定感、議論を形にする実務力、的確で無駄のない発言。"}, {"label": "やりすぎると逆効果になる行動", "text": "記録や時間管理に徹して意見を出さない、「黙って作業している人」に見えてしまう。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "自分の担当範囲がはっきりしていて、「ここはあなたに任せる」と言われる環境で、あなたは本来の力を発揮します。逆に、誰の仕事かわからない業務が降ってきたり、会議ばかりで作業時間が取れなかったりすると、静かにエネルギーが削られていく。誰かに頼られるより、「自分の手で確実に仕上げた」という実感が、あなたの満足の源です。"}, {"label": "活躍しやすいポジション", "text": "専門領域を任される担当者やスペシャリスト。範囲と責任がはっきりした仕事で力を最大化できます。"}, {"label": "組織の中で担いやすい役割", "text": "業務の要となる実務担当、品質を守る最後の砦、後輩への技術指導役。"}, {"label": "目指しやすいキャリア", "text": "経理・財務、ITエンジニア（運用・保守・インフラ）、技術職、資格を活かす専門職（税理士・社労士など）。"}, {"label": "特徴を活かした未来像", "text": "専門スキルを10年かけて磨き、「この業務はこの人がいれば大丈夫」と社内外で頼られるプロになっている。静かだけれど確かな存在感が、あなたの武器です。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "必要なことだけを短く伝えるあなたの話し方は、効率的な反面、「怒ってる？」と思われることがありませんか。本人はいたって普通のつもりなのに、相手が構えてしまう。また、自分で処理したほうが早いと感じて、気づけば他の人に仕事を渡さなくなっている。その結果、仕事が自分に集中して、静かに疲れが溜まっていくパターンに、心当たりがあるかもしれません。"}, {"label": "強みが裏目に出るパターン", "text": "処理が速いぶん「自分でやる」ことが増え、ノウハウが属人化する。"}, {"label": "人間関係で気をつけること", "text": "必要以上に関わらないスタイルが「冷たい」と誤解されやすい。挨拶とひと声かけを意識するだけで印象が変わります。"}, {"label": "チームで働く際の注意点", "text": "自分の進め方を周りにも共有して、他の人も同じ品質で動けるようにする。"}, {"label": "意思決定のクセ", "text": "慣れた方法を選びがちで、より良いやり方を見逃すことがある。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "読む", "text": "志望企業の技術ブログ・採用ブログ・社員の登壇資料を、3本読む。"}, {"label": "書き出す", "text": "「使っている道具」「作業の手順」「品質の確認方法」の3つを書き出す。"}, {"label": "聞く", "text": "面談や座談会で、書き出した内容のうち1つについて、「実際の現場ではどうですか」と質問する。"}, {"label": "伸ばしたいこと", "items": ["専門分野の基礎知識・資格（簿記、ITパスポート、基本情報技術者など）", "周囲を巻き込むコミュニケーション力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、エントリーシートの提出期限を守る点では完璧なのに、「自分の魅力を言葉にする」作業になると手が止まっていませんか。実績や成果は確かにあるのに、「それを人に誇るのは違う気がする」と感じてしまう。面接でも、聞かれたことには正確に答えるけれど、プラスアルファの熱量が伝わりにくい。そのもどかしさを、感じたことがあるはずです。"}, {"label": "企業選びのポイント", "text": "総合職で入るとジョブローテーションで専門が定まらないことがある。職種別採用か、配属の決まり方を確認する。"}, {"label": "面接で強みを伝えるには", "text": "「〇〇の業務を△分短縮した」「ミスゼロで□件処理した」など、スピードと正確さを数字で示す。"}, {"label": "自己PRで気をつけること", "text": "淡々と話すと熱意が伝わりにくい。「なぜそのスキルを磨きたいのか」を一言添える。強みが「正確さ」なら、弱みは「新しい方法への切り替えに時間がかかること」と裏表にする。"}, {"label": "適性検査での傾向", "text": "慎重性や持続性が高く、社会的内向性も高めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["配属・職種がどう決まるか確認したか", "専門スキルを伸ばせる研修・資格支援があるか調べたか", "一人で担当を持てるまでの期間を把握したか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "集中して作業できる時間が確保されていて、「やるべきこと」と「評価される基準」が明確。そんな環境にいると、あなたは余計なことを考えず、淡々と力を伸ばせます。逆に、飲み会や社内イベントへの参加が暗黙の義務だったり、評価の基準が曖昧で「空気を読む力」ばかり求められたりする職場では、実力以前に消耗してしまう。「何を求められているのか」が明確なことが、あなたにとっては大きな安心です。"}, {"label": "相性の良い業界の例", "text": "メーカー（技術・品質部門）、IT（SIer・社内SE）、会計・税理士事務所、金融の事務・システム部門、インフラ。"}, {"label": "相性の良い職種の例", "text": "経理・財務、ITエンジニア、品質管理、生産管理、法務・知財、専門職。"}, {"label": "活躍しやすい会社の特徴", "text": "職務範囲が明確、専門性が評価される、資格取得支援がある、働き方が安定している。"}, {"label": "ミスマッチになりやすい環境", "text": "役割が曖昧で何でも屋になる職場、頻繁な異動、飲み会などのチーム行事が重視される文化。"}, {"label": "このタイプに合いやすい理由", "text": "即応（A）で業務を素早く処理でき、安定（S）の環境で品質を積み上げられ、独立（I）で自分のペースを守り、自己実現（G）として専門性が着実に伸びるからです。キャリアアンカーでは、専門・職能別能力と保障・安定が中心になる傾向です。"}]}], "ASIP": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "誰も見ていなくても、確実にやり切る人。"}, {"label": "このタイプの特徴", "text": "トラブルが起きたとき、周りが慌てる中で、あなたは不思議と冷静になります。「まず何をすべきか」が頭の中で整理されて、気づけば静かに動き出している。そして落ち着いたあと、周りが「あの人がいてくれて助かった」と言っているのを、あとから別の人づてに聞くこともあるはずです。あなたの価値は、目立つ場面よりも、何も起きなかった日常の中にあります。"}, {"label": "代表的な強み", "text": "責任感、緊急時の冷静な対応、ルールを守る誠実さ、一人で持ち場を任せられる自律性。"}, {"label": "力が発揮される場面", "text": "トラブルや緊急事態の初動対応、決められた手順を確実に守る業務、担当を任されたアルバイトや係の仕事。"}, {"label": "他タイプと異なる特徴", "text": "誰も見ていなくても手を抜かない点。社会貢献の想いを、派手な活動ではなく日々の確実な仕事で表現できる人です。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "責任感が強く、一人で抱えて自分を責めやすい。"}, {"label": "このタイプの特徴", "text": "責任感が強いぶん、ミスをしたときの自分への当たりが厳しくないでしょうか。周りが「気にしなくていいよ」と言ってくれても、頭の中で何度も反省会を開いてしまう。また、困ったときに「助けて」と言うのが苦手で、限界まで一人で抱えてしまう。自分の頑張りをアピールするのは「出しゃばっている気がして」ためらってしまい、結果として正当に評価されないことへの小さな不満が積もっているはずです。影の部分（普段あまり使わない側）は、自分を前に出して語ること、そして未知の挑戦に先頭で飛び込むことです。"}, {"label": "つまずきやすいこと", "text": "自分の頑張りをアピールしない、変化や新しい取り組みに慎重すぎる、一人で抱え込んで助けを求めにくい。"}, {"label": "力が発揮される場面", "text": "自己PRや面接のように自分を売り込む場面、チームで新しい企画を出す課題、評価が目立つ成果に偏る職場。"}, {"label": "弱みをカバーする方法", "text": "自分の仕事が「誰の役に立ったか」を記録しておく、困ったら相談する基準を決める（例：30分悩んだら聞く）。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDで盛り上がっている議論を聞きながら、あなたは「この案、実際にやるとなると大丈夫かな」と、冷静にリスクを考えていませんか。その一言を言うべきか迷いつつ、水を差してしまいそうで黙ってしまうこともある。でも、言ってみたら「確かにそうだね」と場が落ち着いた経験もあるはずです。あなたの視点は、議論の安全装置になっています。"}, {"label": "向いている役割", "text": "書記（論点チェック役）。"}, {"label": "自然にできる立ち回り", "text": "前提条件やルールの確認、議論の抜け漏れの指摘、「その案は現実に実行できるか」のチェック。"}, {"label": "評価されやすいポイント", "text": "冷静さ、リスクへの目配り、チームの結論の質を上げる確認力。"}, {"label": "やりすぎると逆効果になる行動", "text": "懸念点ばかり挙げて議論を止める、発言が少なすぎて存在感がなくなる。指摘をするときは代案を添えましょう。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "役割が明確で、手順やルールが整っている職場にいると、あなたは安心して力を出せます。逆に、毎回やり方が変わったり、責任の所在が曖昧だったりする環境では、不安が募って落ち着かない。「自分の仕事が誰かの安全や安心につながっている」と実感できる仕事ほど、疲れていても続けられる。それがあなたの原動力です。"}, {"label": "活躍しやすいポジション", "text": "社会や組織の「守り」を担う持ち場の責任者。役割と責任が明確なほど力を発揮します。"}, {"label": "組織の中で担いやすい役割", "text": "安全・品質・コンプライアンスを守る担当、緊急時に頼れる実務者、現場の信頼の要。"}, {"label": "目指しやすいキャリア", "text": "公務員（行政・消防・警察など）、インフラの保守・運用技術者、医療系専門職、品質保証、防災・危機管理。"}, {"label": "特徴を活かした未来像", "text": "災害やトラブルのときに真っ先に頼られ、「この人がいるから安心」と言われる、社会の安全を支えるプロになっている。見えないところで、たくさんの日常を守っています。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "頑張りすぎて、気づけば心も体も限界に近づいていた。そんな経験はありませんか。周りに心配をかけたくなくて、「大丈夫」と言い続けてしまう。そしてある日突然、何もやる気が出なくなる。あなたのように責任感の強い人ほど、そうしたサインを見逃しやすいのです。小さな違和感の段階で、少しだけ口にしてみることが、自分を守る一番の方法です。"}, {"label": "強みが裏目に出るパターン", "text": "責任感が強すぎて自分を追い込む、ルールにこだわりすぎて柔軟な対応ができなくなる。"}, {"label": "人間関係で気をつけること", "text": "口数が少ないと誤解されやすい。感謝やねぎらいは言葉にして伝える。"}, {"label": "チームで働く際の注意点", "text": "自分の担当で問題が起きたら、一人で解決しようとせず早めに共有する。"}, {"label": "意思決定のクセ", "text": "「失敗しないほう」を選びがちで、成長のチャンスを逃すこともある。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "用意する", "text": "次の面接・面談の逆質問を、事前に3つ用意する（改善の提案が通った実例、困ったときの相談先、一人で任される仕事の範囲）。"}, {"label": "聞く", "text": "逆質問の時間に、現場の社員へ直接たずねる。答えを、「いつ・誰が・どう決めたか」までメモする。"}, {"label": "使う", "text": "答えをもとに、「受け身で終わらず、提案できる職場か」を、志望度の判断材料として書き残す。"}, {"label": "伸ばしたいこと", "items": ["志望分野に必要な資格・専門知識", "自分の仕事の価値を言葉で伝える力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、周りの学生が堂々と自己PRをしているのを見て、「自分にはあんなにアピールできることがない」と落ち込んでいませんか。実際には、コツコツ続けてきたことや、任された役割をきちんと果たしてきた経験が山ほどある。ただ、それを「普通のこと」と思っているだけです。面接で緊張しやすいのも、真面目に準備しているからこその反応です。"}, {"label": "企業選びのポイント", "text": "「安定」の中身を確認する。公的な仕事でも、異動・転勤・夜間対応など負担が大きい場合がある。成長機会の有無もあわせて見る。"}, {"label": "面接で強みを伝えるには", "text": "「〇〇の役割を任され、△の状況で□の対応をしてトラブルを防いだ」と、責任を果たした具体例で語る。"}, {"label": "自己PRで気をつけること", "text": "「真面目です」だけで終わらせず、真面目さが生んだ結果（ミス削減・信頼獲得など）を示す。強みが「責任感」なら、弱みは「抱え込みやすさ」と裏表にする。"}, {"label": "適性検査での傾向", "text": "慎重性や持続性が高く、自責性も高めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["その仕事が「誰の、どんな安心」を守っているか言えるか", "勤務形態（シフト・当番・転勤）を把握したか", "一人で担当を持つ仕事か、常にチームで動く仕事か確認したか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "「ルールは何のためにあるのか」を大切にする組織に入ると、あなたは自分が間違っていないと感じられて、自然と力が出ます。逆に、成果のためならルールを曲げることを良しとするような職場では、表には出さなくても、心の中でずっと違和感を抱え続けてしまう。誠実さが評価される環境かどうかは、あなたにとって何よりも大切な条件です。"}, {"label": "相性の良い業界の例", "text": "官公庁・自治体、インフラ（電力・ガス・水道・鉄道・通信）、医療、警備・防災、食品・製薬の品質部門。"}, {"label": "相性の良い職種の例", "text": "行政職、保守・運用技術者、品質保証・検査、医療専門職、総務・リスク管理。"}, {"label": "活躍しやすい会社の特徴", "text": "社会的役割が明確、手順とルールが整っている、長期的に安定して働ける、誠実さが評価される文化。"}, {"label": "ミスマッチになりやすい環境", "text": "目立つ成果だけが評価される職場、方針が頻繁に変わるベンチャー、ノルマや競争の強い営業組織。"}, {"label": "このタイプに合いやすい理由", "text": "即応（A）で緊急時にも素早く動け、安定（S）の仕組みの中で確実に責任を果たせ、独立（I）で自分の持ち場を守り、社会貢献（P）を日々の仕事で実感できるからです。キャリアアンカーでは、保障・安定と奉仕・社会貢献が中心になる傾向です。"}]}], "DCTG": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "先を読んで道筋を描き、チームを動かす人。"}, {"label": "このタイプの特徴", "text": "あなたは、議論が混乱しているとき、「結局、論点はこの3つだよね」と整理する力を持っています。本人は当たり前のことをしているつもりでも、周りから見ると「頭の中を見える化してくれる人」。さらに、整理するだけでなく、「じゃあ、こう動こう」と次の行動まで描けるから、チームの迷いが一気に晴れる。静かな顔の裏で、かなり熱い野心を燃やしているのも、あなたの魅力です。"}, {"label": "代表的な強み", "text": "論理的に考える力、全体を見渡す戦略眼、新しいアイデアを形にする構想力、チームを方向づける説得力。"}, {"label": "力が発揮される場面", "text": "ビジネスコンテスト、ゼミの研究発表、企画立案、チームの方針決め、ケース面接。"}, {"label": "他タイプと異なる特徴", "text": "考えるだけでも、動くだけでもなく、挑戦を戦略に落とし込んでチームで実行まで持っていける点。理論と巻き込み力を両立できる人は希少です。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "考えすぎて着手が遅れ、正論で相手を追い込みやすい。"}, {"label": "このタイプの特徴", "text": "準備が完璧でないと、動き出すのが怖くなることはありませんか。「もう少し調べてから」「あと一つ確認してから」と先延ばしにしているうちに、周りの人が先に動いて、悔しい思いをしたことがあるはず。また、正論で相手を追い詰めてしまい、「言い方がきついよ」と言われて、自分でも驚いた経験があるかもしれません。本当は人の気持ちを大切にしたいのに、頭が先に答えを出してしまうのです。影の部分（普段あまり使わない側）は、直感でその場で動くこと、そして一人で黙々と続けることです。"}, {"label": "つまずきやすいこと", "text": "考えすぎて着手が遅れる、完璧な計画を求めすぎる、正論で相手を追い詰めてしまう。"}, {"label": "力が発揮される場面", "text": "スピード勝負の選考、情報が少ない中での即決、感情への配慮が必要な人間関係。"}, {"label": "弱みをカバーする方法", "text": "「70点で一度出す」ルールを持つ、考える時間に期限を設ける、意見を言う前に相手の考えを一度受け止める。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDが始まると、あなたは最初の数分で「このグループの力関係」「議論のゴール」「時間配分」を頭の中で素早く計算しているはずです。そして議論が脱線しかけた瞬間、「一度整理しますね」と切り出す。その発言が通ると、場の空気が一段引き締まって、ちょっとした快感を覚える。ただ、気づけば進行を仕切りすぎて、「自分は議論の中身にちゃんと貢献できたかな」と不安になる瞬間もあるのではないでしょうか。"}, {"label": "向いている役割", "text": "ファシリテーター（議論の設計役）。"}, {"label": "自然にできる立ち回り", "text": "冒頭で論点と進め方を整理する、出た意見を構造化して比較軸を示す、最後に結論を論理的にまとめる。"}, {"label": "評価されやすいポイント", "text": "論理性、議論の構造化、チームを結論に導くリーダーシップ。"}, {"label": "やりすぎると逆効果になる行動", "text": "議論の進め方を細かく決めすぎて窮屈にする、他者の意見を論理で切り捨てる、「正解」を一人で決めてしまう。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "全体の方向性を決める場面で、あなたの意見が自然と求められる、そんな経験はありませんか。逆に、背景の説明がないまま「とりあえずこれをやって」と言われる状況では、頭の中が「なぜ？」で埋まって、手が動かなくなる。「何のためにやるのか」が見えているとき、あなたの力は何倍にもなります。裏を返せば、納得できない仕事には、驚くほど静かに力が抜けていきます。"}, {"label": "活躍しやすいポジション", "text": "チームの方向性を決める参謀・戦略担当。行動力のあるメンバーと組むと、構想が一気に実現します。"}, {"label": "組織の中で担いやすい役割", "text": "プロジェクトの企画責任者、経営企画、チームの知的リーダー。"}, {"label": "目指しやすいキャリア", "text": "戦略コンサルタント、経営企画、商品企画・マーケティング、プロダクトマネージャー、将来的な経営幹部。"}, {"label": "特徴を活かした未来像", "text": "30代で事業戦略を任され、自分が描いた構想をチームで実現し、会社の新しい柱をつくっている。「あの人の描く絵はいつも当たる」と言われるようになります。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "頭の中で完璧なシナリオを描くほど、現実がその通りにならないときの落胆が大きくなりませんか。チームメンバーが想定外の動きをしたとき、内心ではイライラするのに、顔には出さず飲み込んでしまう。その積み重ねで、「本当はわかってもらえていない」という孤独を感じることもあるでしょう。あなたの思考は深いぶん、周りと温度差が生まれやすいのです。"}, {"label": "強みが裏目に出るパターン", "text": "分析に時間をかけすぎてチャンスを逃す、論理的に正しくても人の気持ちがついてこない。"}, {"label": "人間関係で気をつけること", "text": "「なぜ？」を連発すると、相手は責められていると感じる。質問の前に共感の一言を添える。"}, {"label": "チームで働く際の注意点", "text": "自分の計画を押しつけず、メンバーの意見を取り入れる余白を残す。"}, {"label": "意思決定のクセ", "text": "選択肢を比べ続けて決めきれないことがある。「決める期限」を先に決めておく。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "調べる", "text": "志望業界の企業を3社選び、企業サイトの「IR情報」から決算資料か中期経営計画を開く。"}, {"label": "まとめる", "text": "「会社が置いている目標」「その目標を担う部署」「数字で変化した点」を、1社1枚にまとめる。"}, {"label": "確かめる", "text": "そのうち1社の社員面談かOB・OG訪問で、まとめた内容が現場の実感と合っているかを聞く。"}, {"label": "伸ばしたいこと", "items": ["スピード感（考えながら動く力）", "人の感情に寄り添うコミュニケーション力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、企業研究に時間をかけすぎて、気づけばエントリーの締め切りが近づいていた、ということはありませんか。ESも「もっと良い切り口があるはず」と何度も書き直して、結局最初の案に戻る。面接では論理的に話せているのに、「もう少し、あなた自身の言葉で聞かせてください」と言われて、答えに詰まった経験もあるはずです。"}, {"label": "企業選びのポイント", "text": "「戦略に関われる」と思って入っても、最初は現場業務が中心のことが多い。企画職になるまでの道のりを確認する。"}, {"label": "面接で強みを伝えるには", "text": "「課題を〇〇と分析し、△の戦略を立て、チームで実行して□の成果を出した」と、分析、実行、成果の流れで語る。"}, {"label": "自己PRで気をつけること", "text": "理屈っぽく長くなりがちなので、結論から話して1分以内に収める。強みが「戦略的思考」なら、弱みは「慎重になりすぎること」と裏表にする。挑戦を語るときはリスクをどう考えたかも添える。"}, {"label": "適性検査での傾向", "text": "内省性や慎重性が高く、達成意欲も高めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["若手が企画・戦略に関わった具体例を知っているか", "その会社の今後の事業戦略を自分の言葉で説明できるか", "挑戦を評価する仕組み（新規事業制度・提案制度）があるか確認したか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "論理的な議論を歓迎してくれて、年次に関係なく意見を言える環境にいると、あなたは水を得た魚のように力を発揮します。反対に、「前例がこうだから」の一言で議論が終わってしまう職場では、頭の中で「なぜ？」が溜まり続けて、静かに消耗していく。考えることを歓迎してくれる場所かどうかが、あなたにとっては重要な分かれ道です。"}, {"label": "相性の良い業界の例", "text": "コンサルティング、IT・Webサービス、総合商社、広告・マーケティング、メガベンチャー。"}, {"label": "相性の良い職種の例", "text": "コンサルタント、経営企画、商品企画、マーケティング、プロダクトマネージャー。"}, {"label": "活躍しやすい会社の特徴", "text": "論理的な議論が歓迎される、若手の提案が通る、チームで大きなプロジェクトに取り組む、成長機会が多い。"}, {"label": "ミスマッチになりやすい環境", "text": "前例踏襲が強い、考える時間が与えられないスピード一辺倒の職場、トップダウンで意見が言えない組織。"}, {"label": "このタイプに合いやすい理由", "text": "熟考（D）で戦略を練り、挑戦（C）で新しいことに取り組み、協働（T）でチームを動かし、自己実現（G）の成長欲求が大きなプロジェクトで満たされるからです。キャリアアンカーでは、経営管理と起業家的創造性が強い傾向です。"}]}], "DCTP": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "課題の本質を見抜き、立場の違う人をまとめる人。"}, {"label": "このタイプの特徴", "text": "あなたは、意見が対立している二人の間に立ったとき、双方の言い分を聞いて「実はここは同じことを言っているよね」と気づける人です。感情だけでも、理屈だけでもなく、両方を行き来できるから、立場の違う人たちから信頼される。あなたの周りには、気づけば「話を聞いてほしい」と集まる人が増えているはずです。"}, {"label": "代表的な強み", "text": "課題の本質を見抜く分析力、仕組みで解決する構想力、多様な人をまとめる合意形成力、長期的な視点。"}, {"label": "力が発揮される場面", "text": "社会課題をテーマにした研究やゼミ、政策提言コンテスト、団体の運営改善、利害関係者が多いプロジェクト。"}, {"label": "他タイプと異なる特徴", "text": "熱い想いを、実現可能な設計図に変えられる点。感情だけでも理屈だけでもなく、両方で人を動かせます。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "理想が大きく、全員の納得を探して決断が遅れやすい。"}, {"label": "このタイプの特徴", "text": "理想を語るとき、頭の中では「もっとこうあるべき」という像がはっきりしているのに、現実とのギャップに疲れてしまうことはありませんか。全員が納得する形を探しているうちに、決断が遅れて、結局何も進まなかった。そんな悔しさを味わったことがあるはず。また、行動に移す前に「本当にこれで合っているか」を何度も確認してしまい、周りに「慎重だね」と言われるのも、実は少し気にしています。影の部分（普段あまり使わない側）は、その場の勢いで動くこと、そして自分の都合を優先することです。"}, {"label": "つまずきやすいこと", "text": "理想が高く計画が壮大になりすぎる、慎重さゆえに行動が遅れる、関係者全員を納得させようとして疲弊する。"}, {"label": "力が発揮される場面", "text": "短期で成果を求められる仕事、スピード重視のベンチャー、利益最優先の判断。"}, {"label": "弱みをカバーする方法", "text": "大きな構想を「最初の一歩」に分解する、小さく試して検証する。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDで意見が割れかけると、あなたは真っ先に「それぞれの意見の共通点って何でしょう？」と口にしていませんか。議論の対立を見ていられない気持ちと、「どうすればみんなが納得できるか」を考える頭の働きが、同時に動き出す。そして、全員が納得する着地点が見えたとき、静かな達成感を覚える。ただ、そこに至るまでに時間をかけすぎて、時間切れになりそうな冷や汗も、あなたはよく知っているはずです。"}, {"label": "向いている役割", "text": "ファシリテーター（合意形成役）。"}, {"label": "自然にできる立ち回り", "text": "議論の目的と評価基準を最初にそろえる、対立する意見の共通点を見つけて統合する、社会的な意義の観点を加える。"}, {"label": "評価されやすいポイント", "text": "視野の広さ、論理性と配慮の両立、チームを合意へ導く力。"}, {"label": "やりすぎると逆効果になる行動", "text": "議論を抽象的で大きな話に広げすぎる、全員の納得を待って時間切れになる。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "数字や効率だけで物事が決まる場面では、あなたは少し息苦しさを感じるはずです。「それで、そのやり方で本当に救われる人は誰なのか」という問いが、頭の片隅から離れない。逆に、長い時間をかけて仕組みを変えていくような仕事では、地味な作業が続いても、不思議と気持ちが折れません。長期的な視点で社会の土台に関わることが、あなたの仕事観の中心にあります。"}, {"label": "活躍しやすいポジション", "text": "多くの関係者をつなぎ、仕組みをつくる設計者・プロデューサー。実行力のあるメンバーと組むと、構想が現実になります。"}, {"label": "組織の中で担いやすい役割", "text": "プロジェクトの企画・調整役、部門間・組織間の橋渡し役、制度や仕組みの設計担当。"}, {"label": "目指しやすいキャリア", "text": "国家公務員（政策立案）、シンクタンク研究員、公共・ソーシャル領域のコンサルタント、教育・医療の事業企画、サステナビリティ推進責任者。"}, {"label": "特徴を活かした未来像", "text": "自分が設計した制度やサービスが社会に広がり、「この仕組みのおかげで助かった」という人が何千人もいる。目立たなくても、社会の土台を静かに変えている姿です。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "正しいことを言っているはずなのに、なぜか相手が心を閉ざしてしまった。そんな経験はありませんか。あなたは論理で説明すれば伝わると思っているけれど、相手が求めていたのは、「まず気持ちをわかってほしい」だったのかもしれない。頭ではわかっているのに、いざという場面で理屈が先に出てしまう。その後悔を、家に帰ってから一人で反芻していませんか。"}, {"label": "強みが裏目に出るパターン", "text": "完璧な仕組みを求めて実行が遅れ、目の前で困っている人を待たせてしまう。"}, {"label": "人間関係で気をつけること", "text": "正しさを語りすぎて「上から目線」と受け取られないよう、現場の人の声に耳を傾ける。"}, {"label": "チームで働く際の注意点", "text": "構想を共有するときは、抽象論より具体的な「次の行動」をセットで伝える。"}, {"label": "意思決定のクセ", "text": "全員の合意を目指して決断が遅れる。「最終的に誰が決めるか」を最初に決めておく。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "参加する", "text": "自治体やNPOの公開イベント・講座・シンポジウムを1つ探して参加する（市区町村のサイト、イベント情報サイトで探す）。"}, {"label": "聞く", "text": "実務者に、「課題をどんな指標で測っているか」「成果が出たと判断する基準」「意義と費用のバランスをどうとっているか」を聞く。"}, {"label": "使う", "text": "聞いた指標を志望先の「成果の測り方」と比べ、志望動機の「なぜこの会社か」に使う。"}, {"label": "伸ばしたいこと", "items": ["データ分析・統計の基礎", "小さく始めてすぐ改善する実行スピード"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、「社会に貢献できる仕事」を探すあまり、どの業界を見ても「でも、ここも一部の課題にしか関わっていない」と感じてしまい、選べなくなっていませんか。志望動機を考えるときも、壮大な話から入って、「結局、あなたは何をしたいの？」と聞かれて、言葉に詰まった経験があるかもしれません。大きな視点を持っていること自体が、すでに強みなのです。"}, {"label": "企業選びのポイント", "text": "社会への影響力の大きさと、自分が若手のうちに関われる範囲は別。何ができるかを確認する。"}, {"label": "面接で強みを伝えるには", "text": "「〇〇の課題を分析し、△の仕組みを提案・実行して、□人の関係者をまとめた」と、構想と実行の両方を語る。"}, {"label": "自己PRで気をつけること", "text": "社会貢献したいだけでは評価されにくいので、自分が実際にやったことを中心に。強みが「構想力」なら、弱みは「着手が慎重になりすぎること」と裏表にする。"}, {"label": "適性検査での傾向", "text": "内省性や慎重性が高く、達成意欲が高めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["その組織が社会課題にどう関わっているか（直接・間接）を説明できるか", "若手が企画・提案に関わる機会があるか確認したか", "長期的に取り組みたいテーマと、その組織の事業が重なっているか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "利害関係者が多く、調整に時間がかかる仕事を「面倒」と感じる人もいますが、あなたはそこに、むしろ面白さを見つけるはずです。立場の違う人たちの間を取り持ち、少しずつ全体が前に進む感覚が、あなたには心地いい。反対に、短期の数字だけを追う環境や、「考える暇があったら動け」という空気の職場では、本来の強みが「遅さ」と誤解されてしまいます。"}, {"label": "相性の良い業界の例", "text": "官公庁、シンクタンク、コンサルティング（公共・ソーシャル領域）、教育、医療・ヘルスケア、エネルギー・環境、インフラ企業の企画部門。"}, {"label": "相性の良い職種の例", "text": "政策立案、リサーチャー、コンサルタント、事業企画、サステナビリティ推進、まちづくりプランナー。"}, {"label": "活躍しやすい会社の特徴", "text": "社会的ミッションが明確、長期視点で事業を考える、多様な関係者と協働する機会が多い。"}, {"label": "ミスマッチになりやすい環境", "text": "短期の数字だけが評価軸、考える時間がないスピード重視の職場、社会との接点が見えない仕事。"}, {"label": "このタイプに合いやすい理由", "text": "熟考（D）で課題を深く分析し、挑戦（C）で新しい仕組みを構想し、協働（T）で多くの人を巻き込み、社会貢献（P）を大きなスケールで実現できるからです。キャリアアンカーでは、奉仕・社会貢献と経営管理が重なる傾向です。"}]}], "DCIG": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "納得するまで掘り下げ、根拠のある答えを出す人。"}, {"label": "このタイプの特徴", "text": "他の人が「そういうものだから」で済ませてしまうことに、あなたは「本当にそうなのかな」と引っかかります。その小さな違和感を放っておけず、調べ、試し、自分なりの答えを作ってしまう。その結果、周りが気づかなかったことに最初に気づいたり、誰も思いつかなかった方法を見つけたりする。あなたの頭の中は、実はとても静かで、とても騒がしい場所です。"}, {"label": "代表的な強み", "text": "探究心、独創的な発想、深く考える力、一人で没頭できる集中力、知的好奇心。"}, {"label": "力が発揮される場面", "text": "卒業研究、プログラミングや創作など個人での作品づくり、新しい技術の独学、難しい問題の解決。"}, {"label": "他タイプと異なる特徴", "text": "誰も考えていない問いを立て、深く掘って独自の答えを出せる点。表面的なアイデアではなく、根拠のある新しさを生み出せます。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "没頭するほど周りが見えず、伝え方が後回しになる。"}, {"label": "このタイプの特徴", "text": "自分の考えを説明するとき、頭の中ではつながっているのに、順番に話そうとして前提から長くなってしまうことはありませんか。相手の顔が「？」になった瞬間、もういいやと説明を諦めてしまい、あとから「ちゃんと伝えればよかった」と思う。また、納得できないことには、体が動かなくなる。やるべきとわかっていても、動けない自分に、内心イライラしていることもあるはずです。影の部分（普段あまり使わない側）は、その場で素早く反応すること、そして決まった枠の中で安定して続けることです。"}, {"label": "つまずきやすいこと", "text": "興味のないことへのやる気が出にくい、こだわりが強く完成が遅れる、考えが深いぶん前提から話してしまい、要点が伝わるまで時間がかかる。"}, {"label": "力が発揮される場面", "text": "雑務や定型業務、短時間で結論を出す面接やGD、チームでの調整や根回し。"}, {"label": "弱みをカバーする方法", "text": "アウトプットの締め切りを自分で設定する、専門的な内容を「中学生にもわかる言葉」で説明する練習をする。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDで、みんなが同じような案を出し合っているとき、あなたは「この前提、そもそも正しいのかな」と考え込んでしまいませんか。その疑問を言うか迷って、考えがまとまる前に議論が先に進んでしまい、モヤモヤしたまま終わった経験があるはず。逆に、勇気を出して言った一言が議論を変えたときは、静かな手応えがあったのではないでしょうか。"}, {"label": "向いている役割", "text": "書記（根拠チェック・論点整理担当）。"}, {"label": "自然にできる立ち回り", "text": "議論の前提を疑う問いを投げる、他の人と違う視点から解決策を出す、データや根拠に基づいて案を検証する。"}, {"label": "評価されやすいポイント", "text": "独自性、思考の深さ、議論を一段上のレベルに引き上げる発言。"}, {"label": "やりすぎると逆効果になる行動", "text": "自分の関心のある論点に深入りしすぎる、専門用語で周りを置いていく、考え込んで発言が遅れる。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "「この問題、あなたに任せるから好きにやってみて」と言われたとき、あなたは心の底から力が湧いてくるはずです。逆に、細かい手順書通りに進めることを求められる環境では、頭の中が静かになって、いつもの切れ味が消えてしまう。「考える自由」と「試す自由」がある環境かどうかが、あなたにとって働く場所の最大の条件です。"}, {"label": "活躍しやすいポジション", "text": "専門領域を深く掘る研究・開発のスペシャリスト。アイデアを広めてくれる協働型の人と組むと、成果が世に出やすくなります。"}, {"label": "組織の中で担いやすい役割", "text": "技術・知識の第一人者、新しい手法の開拓者、難題の解決担当。"}, {"label": "目指しやすいキャリア", "text": "研究開発職、エンジニア、データサイエンティスト、研究者（大学院進学も選択肢）、技術系スタートアップの創業者。"}, {"label": "特徴を活かした未来像", "text": "自分が深く掘り下げた技術やアイデアが新しい製品やサービスになり、業界の常識を変えている。「あの人の発想はいつも一歩先だ」と言われる姿です。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "夢中になるほど、周りが見えなくなって、気づけば約束の時間や締め切りが過ぎていた。そんな経験はありませんか。悪気はなく、ただ頭がそのことでいっぱいだっただけ。でも、周りからは「自分勝手」「マイペースすぎる」と受け取られてしまう。その誤解に傷つきながら、説明するのも面倒で、そのままにしてしまう。そんな循環に心当たりがあるかもしれません。"}, {"label": "強みが裏目に出るパターン", "text": "こだわりすぎて完成しない、自分の正しさに固執して周りの意見を聞かない。"}, {"label": "人間関係で気をつけること", "text": "興味のない話題でも、相手への関心は示す。雑談も信頼関係づくりの一部です。"}, {"label": "チームで働く際の注意点", "text": "進捗と考えていることを定期的に共有する。「何をしているかわからない人」にならないために。"}, {"label": "意思決定のクセ", "text": "面白さを優先して、現実的な制約（期限・予算・需要）を後回しにしがち。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "頼む", "text": "志望分野の研究員（企業の研究所、大学の先輩、ゼミのOB・OG）に、話を聞く機会をメールでお願いする。"}, {"label": "聞く", "text": "「研究テーマはどう決まるか」「1日のうち調べる時間と会議の割合」「成果が事業にどう使われるか」の3つを聞く。"}, {"label": "試す", "text": "自分の研究・ゼミのテーマを1分で説明して、わかりにくかった点を指摘してもらう。"}, {"label": "伸ばしたいこと", "items": ["専門分野の深い知識とスキル", "自分の考えを伝える説明力・プレゼン力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、「みんなと同じように動く」ことに、どこか違和感を覚えていませんか。説明会の流れも、ESの型も、「なんでこうなんだろう」と考え始めてしまい、気づけば準備が進んでいない。面接で自分の研究や関心を話し出すと止まらなくなるのに、「もっと簡潔に」と言われて、どこを削ればいいのかわからなくなる。その経験は、多くのイノベーター型が通る道です。"}, {"label": "企業選びのポイント", "text": "「研究開発がしたい」なら、配属の決まり方と研究テーマの自由度を必ず確認する。"}, {"label": "面接で強みを伝えるには", "text": "「〇〇という問いを立て、△の方法で検証し、□という新しい結果を得た」と、問い、方法、成果で語る。"}, {"label": "自己PRで気をつけること", "text": "専門的すぎる説明は避け、面接官が専門外でも理解できる言葉で意義を伝える。強みが「探究心」なら、弱みは「興味のないことへの切り替えの遅さ」と裏表にする。"}, {"label": "適性検査での傾向", "text": "内省性が高く、独自性や自己尊重も高めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["若手が新しい技術やテーマに挑戦できる制度（自由研究時間など）があるか", "専門性を評価する人事制度（専門職コース）があるか確認したか", "自分が深めたい分野と、その会社の技術・事業が重なっているか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "成果物で評価される環境、そして「面白い」を評価してくれる環境にいると、あなたは驚くほど生き生きします。反対に、会議の根回しや社内調整に多くの時間を取られる職場では、肝心の「考える時間」が奪われて、心が少しずつ干からびていく。「考える時間を守れるかどうか」は、あなたにとって給料と同じくらい大切な条件です。"}, {"label": "相性の良い業界の例", "text": "メーカー（研究開発部門）、IT・AI、製薬・バイオ、研究機関、ゲーム・コンテンツ制作、技術系スタートアップ。"}, {"label": "相性の良い職種の例", "text": "研究職、開発エンジニア、データサイエンティスト、UXリサーチャー、クリエイター。"}, {"label": "活躍しやすい会社の特徴", "text": "専門性を尊重する、裁量と考える時間が与えられる、新しい挑戦を歓迎する、成果で評価される。"}, {"label": "ミスマッチになりやすい環境", "text": "定型業務中心、細かい指示や管理が多い、専門性よりも年次や調整力が評価される組織。"}, {"label": "このタイプに合いやすい理由", "text": "熟考（D）で深く考え抜き、挑戦（C）で未知のテーマに取り組み、独立（I）で自分のやり方を貫き、自己実現（G）として専門性と創造性を磨き続けられるからです。キャリアアンカーでは、専門・職能別能力と自律・独立、起業家的創造性が強い傾向です。"}]}], "DCIP": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "小さな違和感から、まだない答えを考え抜く人。"}, {"label": "このタイプの特徴", "text": "あなたは、多くの人が見過ごしてしまう小さな違和感を、「これは大事なことかもしれない」と捉えることができます。流行や周りの空気に流されず、自分の頭で考え、自分の言葉で結論を出す。その姿勢は、時に周りから「頑固」と言われることもありますが、実は長い目で見ると、一番ぶれない人として信頼されているはずです。"}, {"label": "代表的な強み", "text": "本質を突く洞察力、信念に基づく粘り強さ、独自の問題意識、専門性で社会に貢献しようとする志。"}, {"label": "力が発揮される場面", "text": "社会課題を扱う研究や論文、調査・分析レポート、個人での発信活動、長期的に取り組むテーマがある活動。"}, {"label": "他タイプと異なる特徴", "text": "流行の社会貢献ではなく、自分で調べ、考え抜いた根拠のある問題提起ができる点。周りが気づかない課題に光を当てられます。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "理想と現実のギャップを、一人で抱えこみやすい。"}, {"label": "このタイプの特徴", "text": "理想と現実の間で、一人で悩み続けていませんか。「もっとこうあるべきなのに」という思いが強いぶん、現実の妥協を見ると、心の中で「本当にこれでいいのか」と引っかかる。そして、その違和感を周りに共有するのが難しく、結局一人で抱え込んでしまう。また、自分の考えが正しいと確信するほど、他人の意見を受け入れる余裕がなくなる瞬間も、自覚しているはずです。影の部分（普段あまり使わない側）は、その場の勢いで動くこと、そして周囲に足並みをそろえることです。"}, {"label": "つまずきやすいこと", "text": "理想と現実のギャップに悩みやすい、自分の考えに固執する、人に頼らず一人で背負い込む、行動に移すまでが長い。"}, {"label": "力が発揮される場面", "text": "利益優先の判断、チームでの妥協や調整、短期間で成果を求められる環境。"}, {"label": "弱みをカバーする方法", "text": "完璧な答えより「今できる一歩」を優先する、同じ志を持つ仲間やメンターとつながる。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDで「どうすれば売上が上がるか」「どうすれば効率が良いか」という話が進むとき、あなたは「でも、そもそもこれって誰のためなんだろう」と、一人で引っかかっていませんか。その疑問を口にしたい気持ちと、「議論の流れを止めてしまうかも」という不安が、頭の中でせめぎ合う。結局、発言のタイミングを逃して、帰り道に「あれを言えばよかった」と後悔する。そんな経験が、あなたには何度かあるはずです。"}, {"label": "向いている役割", "text": "発表者（本質的な問題提起を、発表の軸にする役）。"}, {"label": "自然にできる立ち回り", "text": "「そもそもの課題は何か」を問い直す、見落とされている影響（弱い立場の人、長期的な影響）を指摘する、問い直した内容を発表の軸に据える。"}, {"label": "評価されやすいポイント", "text": "視点の深さ、倫理観、議論の質を高める問いかけ。"}, {"label": "やりすぎると逆効果になる行動", "text": "前提を問い直しすぎて議論が進まない、自分の価値観を正解として主張する。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "「それって、何のためにやるんですか？」と、つい聞いてしまう。そのたびに、周りが少し困った顔をするのに気づいても、聞かずにはいられない。あなたにとっては、意味を理解せずに動くことが、とても苦しいのです。逆に、意義のあるテーマに長期間じっくり向き合える環境では、地味な作業が続いても、驚くほど粘り強く取り組める。これがあなたの本当の強さです。"}, {"label": "活躍しやすいポジション", "text": "専門性を武器に課題を解き明かす研究者・専門家。発信力のある人や実行力のある組織と組むと、影響力が広がります。"}, {"label": "組織の中で担いやすい役割", "text": "調査・研究担当、専門アドバイザー、組織の倫理や方向性を問い直す存在。"}, {"label": "目指しやすいキャリア", "text": "研究者（大学・研究機関）、環境・エネルギー・医療分野の技術者、調査報道の記者、国際機関・NGOの専門職、政策アナリスト。"}, {"label": "特徴を活かした未来像", "text": "長年探究してきたテーマの第一人者として、研究や提言が社会の仕組みを変えるきっかけになっている。あなたの問いが、次の世代の「当たり前」を変えています。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "信念が強いあなたは、意見の違う人と話すとき、表面的には穏やかでも、心の中では「どうしてわかってくれないんだろう」と感じていませんか。そして、その気持ちが顔や態度に少し出てしまい、相手との距離ができてしまう。一方で、孤立したくないという気持ちも、実は人一倍強い。その矛盾に、自分でも気づいているのではないでしょうか。"}, {"label": "強みが裏目に出るパターン", "text": "信念が強すぎて柔軟さを失う、現実的な妥協を「逃げ」と感じて行き詰まる。"}, {"label": "人間関係で気をつけること", "text": "考えの違う人を否定しない。異なる立場の意見こそ、解決策を磨く材料になります。"}, {"label": "チームで働く際の注意点", "text": "自分の考えを言語化して共有し、周りに理解してもらう努力を惜しまない。"}, {"label": "意思決定のクセ", "text": "「意義があるか」だけで判断し、生活や待遇を軽視しがち。長く続けるための条件も考える。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "探す", "text": "志望する設計事務所、メーカーのデザイン部門、美術館・文化施設の見学会かオープンデスクを1つ探して、申し込む。"}, {"label": "聞く", "text": "作り手に、「依頼主の要望と自分の考えを、どう折り合いをつけるか」「考える時間はどれくらい取れるか」「批判を受けた作品をどう直すか」を聞く。"}, {"label": "使う", "text": "見た制作物から1つ選び、「なぜその形か」を自分の言葉で説明してみる。"}, {"label": "伸ばしたいこと", "items": ["専門分野の知識と研究・分析の手法", "考えを人に伝わる形にする発信力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、「企業に入って働く」ことと「自分の信念を貫く」ことの間で、迷っていませんか。説明会では「素敵な理念だな」と思いつつ、その裏にある現実を想像して、「本当にこの会社で自分のやりたいことができるのか」と冷静に見てしまう。そのぶん、周りが次々と選考を進める中で、自分だけ立ち止まっているように感じて焦る。でも、その慎重さは、後悔しない選択をするための大切な時間です。"}, {"label": "企業選びのポイント", "text": "社会的意義の高さだけで選ばず、自分の専門性を活かせるか、伸ばせるかも同じ重さで見る。"}, {"label": "面接で強みを伝えるには", "text": "「〇〇という課題に問題意識を持ち、△を調べて考え、□という提案・行動につなげた」と、問題意識、探究、行動で語る。"}, {"label": "自己PRで気をつけること", "text": "理念や理想の話だけで終わらせず、実際に取った行動と結果を必ず入れる。強みが「探究心」なら、弱みは「考えを曲げにくいこと」と裏表にする。"}, {"label": "適性検査での傾向", "text": "内省性や独自性が高く、従順性は低めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["自分の探究テーマとその組織の事業・研究が重なっているか", "専門性を伸ばせる環境（研究時間・専門職制度・留学支援など）があるか", "社会への貢献の仕方（直接・間接）に自分が納得できるか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "「なぜこの仕事をするのか」を、メンバー全員が自分の言葉で語れる職場。そんな環境にいると、あなたは余計な迷いがなくなって、一気に力を発揮できるはずです。逆に、目先の売上のために理念が後回しにされる環境では、日々の仕事の中で「これは本当に正しいのか」という疑問が積み重なり、静かに心が疲れていきます。"}, {"label": "相性の良い業界の例", "text": "大学・研究機関、シンクタンク、国際機関・NGO、環境・エネルギー、医療・製薬、報道（調査報道）。"}, {"label": "相性の良い職種の例", "text": "研究職、政策アナリスト、技術開発（社会課題分野）、記者、専門コンサルタント。"}, {"label": "活躍しやすい会社の特徴", "text": "専門性と独自の視点が尊重される、長期的なテーマに取り組める、社会的使命が明確。"}, {"label": "ミスマッチになりやすい環境", "text": "短期の利益だけを追う、上意下達で意見が通らない、社会的意義を感じにくい仕事。"}, {"label": "このタイプに合いやすい理由", "text": "熟考（D）で課題を深く掘り下げ、挑戦（C）で新しい答えを探し、独立（I）で自分の信念を貫き、社会貢献（P）を専門性という形で実現できるからです。キャリアアンカーでは、奉仕・社会貢献と専門・職能別能力、自律・独立が重なる傾向です。"}]}], "DSTG": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "先回りで準備して、チームの土台を固める人。"}, {"label": "このタイプの特徴", "text": "あなたが関わったプロジェクトは、なぜか大きなトラブルなく進みます。それは偶然ではなく、あなたが事前に「起こりそうなこと」を想像して、静かに手を打っているからです。誰も気づかないところでリスクを減らしているので、あなたの貢献は目に見えにくい。でも、あなたがいなくなったとき、周りは初めて「あの人がいたから回っていたんだ」と気づくはずです。"}, {"label": "代表的な強み", "text": "計画力、段取り力、調整力、信頼される誠実さ、長く努力を続ける力。"}, {"label": "力が発揮される場面", "text": "イベントやプロジェクトのスケジュール管理、サークル・部活の運営（会計・副代表など）、試験勉強の計画、チームの進行管理。"}, {"label": "他タイプと異なる特徴", "text": "チームが失敗しないように先回りして整える力。目立たなくても、この人がいるとプロジェクトが確実に回る存在です。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "準備に力を使いすぎ、想定外に切り替えにくい。"}, {"label": "このタイプの特徴", "text": "準備に時間をかけすぎて、疲れ果ててしまうことはありませんか。「万が一」を考えすぎて、あれもこれもと対策を増やし、本番前に力尽きる。また、予定外のことが起きると、パニックまではいかなくても、頭の切り替えに時間がかかる。周りが「まあ、なんとかなるよ」と言う場面で、あなたは「なんとかならなかったらどうするの」と心の中でつぶやいている。そんな自分を、「心配性すぎるかな」と少し気にしているはずです。影の部分（普段あまり使わない側）は、その場の直感で動くこと、そしてリスクを取って飛び込むことです。"}, {"label": "つまずきやすいこと", "text": "想定外の変化に弱い、慎重すぎて新しい挑戦に踏み出しにくい、周りに気を遣いすぎて決断が遅れる。"}, {"label": "力が発揮される場面", "text": "方針が急に変わる状況、正解のない課題、アドリブを求められる面接。"}, {"label": "弱みをカバーする方法", "text": "計画に予備日とプランBを最初から入れておく、想定問答を準備しつつ即興の練習もしておく。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDが始まった瞬間、あなたは「全体で何分ある？」「発表は誰がする？」と、段取りを確認し始めていませんか。意見を出すよりも先に、場を整えることに意識が向いてしまう。ところが、いざ終了時間が近づいて結論を出す段になると、「自分の意見はあまり言えていなかったかも」と焦る。段取りは完璧なのに、自分の存在感が薄かった気がして、帰り道に反省する、そんな経験があるのではないでしょうか。"}, {"label": "向いている役割", "text": "タイムキーパー。"}, {"label": "自然にできる立ち回り", "text": "最初に時間配分を提案する、出た意見を整理して論点を見える化する、終盤に結論を整えて発表の準備をする。"}, {"label": "評価されやすいポイント", "text": "計画性、議論の整理力、チーム全体の成果を考える姿勢。"}, {"label": "やりすぎると逆効果になる行動", "text": "進行管理に集中しすぎて自分の意見がない、計画通りに進めることにこだわって良いアイデアを切り捨てる。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "「この先どうなるのか」が見えている状態で働けると、あなたはとても安心して力を出せます。逆に、先行きが不透明で、毎日のように方針が変わる環境では、表面は平静を保っていても、内側では静かに消耗していく。そして、自分の成長を実感できるのは、「去年の自分より、確かにできることが増えた」と感じられる瞬間です。派手さはなくても、積み上げが見える環境があなたには合っています。"}, {"label": "活躍しやすいポジション", "text": "プロジェクトを確実に回す推進管理・調整役。アイデアマンと組むと、構想を実現させる要になります。"}, {"label": "組織の中で担いやすい役割", "text": "プロジェクトマネジメント、チームの進行管理、部署間の調整役、後輩の育成担当。"}, {"label": "目指しやすいキャリア", "text": "大手企業の総合職から管理職へ、人事・総務・経理などの管理部門、PMO（プロジェクト管理）、金融・保険の企画職。"}, {"label": "特徴を活かした未来像", "text": "着実に経験を積み、30代後半には大きな部署をまとめる信頼厚いマネージャーとして、チームの成長と自分の成長を両立している。「あの人の下で働くと安心する」と言われます。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "周りに気を遣いすぎて、自分の意見を飲み込んでしまった経験はありませんか。「今言わなくてもいいか」「波風を立てたくない」と思って黙った結果、後から「あの時言っておけば」と悔やむ。そんな積み重ねで、「自分の意見は本当は何だったんだろう」とわからなくなる瞬間があるはず。調整役を担うほど、自分の本音が置き去りになりやすいのです。"}, {"label": "強みが裏目に出るパターン", "text": "計画にこだわりすぎて、状況が変わっても修正できない。"}, {"label": "人間関係で気をつけること", "text": "周りに合わせすぎて自分の本音を言わない。意見の対立を避けすぎない。"}, {"label": "チームで働く際の注意点", "text": "細かい管理が「信頼されていない」と受け取られることもある。任せる部分は任せる。"}, {"label": "意思決定のクセ", "text": "リスクを避けるあまり「現状維持」を選びがち。成長のための挑戦も選択肢に入れる。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "探す", "text": "志望する業界で、職場見学か1日〜数日のインターンを1つ探して申し込む（企業の採用ページ、就活サイトのインターン欄）。"}, {"label": "見る", "text": "当日は、「確認の方法（誰が、どの段階で、何を確認するか）」「引き継ぎの方法」「新人が最初に任される作業」を、自分の目で見てメモする。"}, {"label": "比べる", "text": "見た内容を同じ項目で表にして、他社の説明会でも同じ項目で聞いて比べる。"}, {"label": "伸ばしたいこと", "items": ["変化への対応力（計画を柔軟に修正する力）", "自分の意見をはっきり伝える力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、スケジュール管理表を作って、完璧に整えていませんか。ただ、準備が整うほど「完璧にやらなきゃ」というプレッシャーも増え、少しの遅れで焦ってしまう。面接では想定問答を準備しすぎて、想定外の質問が来たとき頭が真っ白になった経験があるかもしれません。準備力は強みですが、「準備の外」への対応も、少しずつ慣れていくことが大切です。"}, {"label": "企業選びのポイント", "text": "安定性だけで選ぶと成長が止まりやすい。「着実に成長できる仕組み」があるかを見る。"}, {"label": "面接で強みを伝えるには", "text": "「〇〇のプロジェクトで計画を立て、△人と調整しながら、期限内に□を達成した」と、計画、調整、成果で語る。"}, {"label": "自己PRで気をつけること", "text": "「縁の下の力持ち」だけだと主体性が見えにくい。自分が判断・提案した場面を入れる。強みが「計画性」なら、弱みは「想定外への弱さ」と裏表にする。"}, {"label": "適性検査での傾向", "text": "慎重性と持続性が高く、気分の波は小さめに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["研修・評価・昇進の仕組みを具体的に説明できるか", "社員の平均勤続年数や離職率を確認したか", "チームで仕事を進める文化があるか、社員の話から確認したか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "ルールや役割が整っていて、「次に何をすべきか」が自然とわかる職場。そんな環境にいると、あなたは余計な不安を抱えずに、自分の力を出せます。教育制度が整い、段階的に任される仕事が増えていくような組織は、あなたの成長リズムに合っています。反対に、毎日が突発対応の連続で、説明もなく役割が変わる職場では、必要以上に消耗してしまいます。"}, {"label": "相性の良い業界の例", "text": "大手メーカー、金融（銀行・保険・証券）、インフラ、大手IT（SIer）、商社、官公庁。"}, {"label": "相性の良い職種の例", "text": "人事・総務・経理、営業企画、プロジェクトマネージャー、生産管理、法人営業。"}, {"label": "活躍しやすい会社の特徴", "text": "教育・評価制度が整っている、チームワーク重視、長期的に働ける、計画的にキャリアを積める。"}, {"label": "ミスマッチになりやすい環境", "text": "方針がころころ変わる、ルールや役割が曖昧、個人プレーと即断即決が求められる職場。"}, {"label": "このタイプに合いやすい理由", "text": "熟考（D）で計画を練り、安定（S）の環境で着実に積み上げ、協働（T）でチームを支え、自己実現（G）として段階的なキャリアアップを実感できるからです。キャリアアンカーでは、保障・安定と経営管理が中心になる傾向です。"}]}], "DSTP": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "話を最後まで聞いて、安心をつくれる人。"}, {"label": "このタイプの特徴", "text": "あなたと話すと、なぜか安心する。そう言われた経験が、きっと何度もあるはずです。あなたは相手の話を急かさず、否定せず、ただそこにいてくれる。その「待てる力」は、実はとても貴重で、誰にでもできることではありません。派手な言葉でなくても、あなたの一言が誰かの支えになっていたことを、本人が知らないままのことも多いでしょう。"}, {"label": "代表的な強み", "text": "傾聴力、思いやり、誠実さ、責任感、周囲との信頼関係を築く力、続ける力。"}, {"label": "力が発揮される場面", "text": "塾講師や家庭教師、後輩の指導、福祉・ボランティア活動、チームの相談役、長期にわたる活動の運営。"}, {"label": "他タイプと異なる特徴", "text": "その場しのぎではなく、相手のためになることを考え抜いて支える点。人に寄り添う優しさと、丁寧に考える慎重さを併せ持っています。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "相手を優先して、自分の意見を飲み込みやすい。"}, {"label": "このタイプの特徴", "text": "自分の意見を言いたい気持ちはあるのに、言葉にする前に「これを言ったら相手はどう思うかな」と考えて、結局飲み込んでしまうことはありませんか。決断を求められたときも、誰かが不満を持たない選択肢を探しているうちに、時間が過ぎていく。そのたびに、「自分ははっきりしない人間なのかも」と、少し自己嫌悪になる。でも、その迷いは、相手を大切に思うからこそ生まれるものです。影の部分（普段あまり使わない側）は、自分の希望を前に出すこと、そしてその場で素早く決めることです。"}, {"label": "つまずきやすいこと", "text": "自分の意見を強く主張できない、変化が苦手、他人と比べられる場面で自分を前に出しにくい、他人の感情に引きずられて疲れやすい、決断に時間がかかる。"}, {"label": "力が発揮される場面", "text": "自己アピールが必要な面接、ノルマや競争の強い環境、スピード重視の職場。"}, {"label": "弱みをカバーする方法", "text": "自分の意見を「私は〜と考えます。理由は〜です」の型で伝える練習をする、人と離れて一人で回復する時間を確保する。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDで意見が割れそうになったとき、あなたは無意識に「どっちの考えも一理ありますね」と間に入っていませんか。全員の意見を丁寧に拾おうとするあまり、自分の意見を言うタイミングを見失い、終わってから「あれ、自分の意見って何だったっけ」と思う。場の雰囲気は良くなったのに、個人としての評価が心配になる。そのジレンマを、何度か経験しているはずです。"}, {"label": "向いている役割", "text": "書記（意見を整理し、発言の少ない人の意見も拾う役）。"}, {"label": "自然にできる立ち回り", "text": "全員の意見を丁寧に聞き取って書き留める、意見の共通点を見つけて整理する、「この案で困る人はいないか」と配慮の視点を入れる。"}, {"label": "評価されやすいポイント", "text": "傾聴力、協調性、議論の整理を通じたチームへの貢献、結論への配慮。"}, {"label": "やりすぎると逆効果になる行動", "text": "全員の意見を尊重しすぎて結論がぼやける、自分の意見を最後まで言わない。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "誰かが少しずつ成長していく様子を、そばで見守る。そんな仕事に、あなたは大きな喜びを感じるはずです。短期的な数字よりも、「半年前より、この人は自信を持てるようになった」という変化に、心が動く。反対に、競争で人を蹴落としたり、成果を急かされたりする環境では、いつの間にか表情が曇ってしまう。人と丁寧に向き合える時間が確保されているかどうかが、あなたの働きやすさを大きく左右します。"}, {"label": "活躍しやすいポジション", "text": "人と組織を支える相談役・育成役。安定した組織の中で、長期的な信頼関係を築ける場所で輝きます。"}, {"label": "組織の中で担いやすい役割", "text": "チームのメンター、顧客や住民の相談窓口、人材育成・研修担当、組織の調和を保つ存在。"}, {"label": "目指しやすいキャリア", "text": "教員、地方公務員（福祉・教育）、人事（育成・労務）、医療・福祉の専門職、地域金融機関の職員。"}, {"label": "特徴を活かした未来像", "text": "何年もかけて育てた人や支えた人から「あなたのおかげで今がある」と言われる、多くの人の人生に寄り添う存在になっている。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "「優しい人」でいようとするあまり、本当は嫌だったことに「大丈夫です」と答えてしまった経験はありませんか。その小さな我慢が積もって、ある日突然、人間関係そのものに疲れてしまう。周りは「急にどうしたの」と驚くけれど、あなたの中では何か月も前から少しずつ溜まっていたのです。限界が来る前に、小さな違和感を言葉にする練習が、あなたを守ります。"}, {"label": "強みが裏目に出るパターン", "text": "相手を思いやりすぎて自分が疲弊する、波風を立てないために問題を先送りする。"}, {"label": "人間関係で気をつけること", "text": "嫌われたくない気持ちから本音を隠しすぎない。誠実さとは、ときに厳しいことを伝えることでもあります。"}, {"label": "チームで働く際の注意点", "text": "自分の負担が大きいときは、早めにSOSを出す。"}, {"label": "意思決定のクセ", "text": "周りの期待や無難さを優先しがち。進路選択は「自分がどうしたいか」を最初に考える。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "申し込む", "text": "志望する福祉・保育・相談の現場で働く社員との面談を、企業の採用窓口か大学のキャリアセンター経由で1件申し込む。"}, {"label": "聞く", "text": "「1人あたりの担当人数」「担当者の心の負担を支える仕組み」「支援の終了や引き継ぎの決め方」の3つを聞く。"}, {"label": "まとめる", "text": "聞いた内容をもとに、「長く寄り添う働き方に無理がないか」を、自分の言葉で1行にまとめる。"}, {"label": "伸ばしたいこと", "items": ["自分の意見を伝える力・交渉力", "ストレスとうまく付き合うセルフケアの習慣"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、周りが「内定が出た」「選考が進んでる」と話しているのを聞いて、焦る気持ちと、「自分のペースで進めたい」気持ちの間で揺れていませんか。面接でも、「自分を良く見せる」ことに抵抗があって、つい控えめに話してしまう。後から「もっと言えたのに」と悔やむことが多いのは、あなたが誠実であるがゆえの反応です。"}, {"label": "企業選びのポイント", "text": "「人の役に立てる」だけで選ばず、職場の人間関係や働き方（残業・異動）も確認する。安定を重視するときは、成長機会もあわせて見る。"}, {"label": "面接で強みを伝えるには", "text": "「〇〇な状況の人に寄り添い、△を工夫して支えた結果、□になった」と、相手の変化まで語る。"}, {"label": "自己PRで気をつけること", "text": "謙虚すぎて自分の貢献が見えなくならないよう、「私が」を主語にして話す。強みが「傾聴力」なら、弱みは「自分の意見を後回しにしやすいこと」と裏表にする。"}, {"label": "適性検査での傾向", "text": "従順性や自責性が高く、回避性（対立を避ける）も高めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["その仕事で「誰を、どう支えるのか」を具体的に言えるか", "社員の雰囲気や人間関係を説明会・訪問で自分の目で確かめたか", "長く働ける制度（休暇・育児支援・異動の頻度）を確認したか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "社員同士が互いを気にかけ、困ったときに声をかけ合える空気。そんな職場に入ると、あなたは本来の穏やかな力を最大限に発揮できます。反対に、陰で人の悪口が飛び交ったり、成果の奪い合いがあったりする環境では、直接の当事者でなくても、空気を吸うだけで消耗してしまう。「どんな人たちと働くか」は、あなたにとって、仕事内容と同じくらい大切な条件です。"}, {"label": "相性の良い業界の例", "text": "教育、官公庁・自治体、医療・福祉、地方銀行・信用金庫、生活インフラ、保険。"}, {"label": "相性の良い職種の例", "text": "教員、行政職、人事・総務、医療・福祉専門職、カウンセラー、窓口・相談業務。"}, {"label": "活躍しやすい会社の特徴", "text": "社会的役割が明確、チームワークと思いやりを大切にする文化、長期的に安心して働ける制度がある。"}, {"label": "ミスマッチになりやすい環境", "text": "成果競争が激しい、ノルマが厳しい、方針が頻繁に変わる、人の顔が見えない仕事。"}, {"label": "このタイプに合いやすい理由", "text": "熟考（D）で相手のことを深く考え、安定（S）の環境で長く寄り添え、協働（T）の中で信頼を築き、社会貢献（P）を日々の関わりの中で実感できるからです。キャリアアンカーでは、奉仕・社会貢献と保障・安定が中心になる傾向です。"}]}], "DSIG": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "一つの専門を深く、正確に磨ける人。"}, {"label": "このタイプの特徴", "text": "あなたが仕上げたものは、細部まで行き届いています。他の人が見落とすような小さなミスに気づき、「ここ、ちょっと違うかも」と直す。その丁寧さは、本人にとっては「普通のこと」でも、周りにとっては「この人に任せると安心」という大きな信頼の源です。そして、コツコツ積み上げた知識や技術は、時間が経つほど価値を増していきます。"}, {"label": "代表的な強み", "text": "分析力、正確さ、粘り強い学習力、品質へのこだわり、一人で深く集中できる力。"}, {"label": "力が発揮される場面", "text": "難関資格の勉強、データ分析やレポート作成、研究、細部まで正確さが求められる作業、長期的なスキル習得。"}, {"label": "他タイプと異なる特徴", "text": "速さよりも深さと正確さで勝負できる点。ミスが許されない仕事や専門知識が必要な仕事で、圧倒的な信頼を得られます。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "完璧を求めて、出すのが遅くなりやすい。"}, {"label": "このタイプの特徴", "text": "「もう少し調べてから」「あと一回見直してから」と、提出を先延ばしにして、結局ギリギリになる。その経験は、きっと一度や二度ではないはずです。また、人に頼るのが苦手で、「自分で調べたほうが確実」と一人で抱え込み、気づけば時間が足りなくなっている。自分の完璧主義がブレーキになっていると知りつつ、止められない。そんな自分に、少し疲れていませんか。影の部分（普段あまり使わない側）は、その場で素早く反応すること、そして周囲を巻き込んで動くことです。"}, {"label": "つまずきやすいこと", "text": "完璧主義で時間がかかる、変化や新しい挑戦を避けがち、自分から人に話しかけたり頼ったりするのが苦手。"}, {"label": "力が発揮される場面", "text": "GDや集団面接など即興の発言が求められる場面、マルチタスク、急な方針変更。"}, {"label": "弱みをカバーする方法", "text": "「どこまでやれば十分か」の基準を事前に決める、面接は想定問答を準備して不安を減らす。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDで他の人が次々と意見を出す中、あなたは頭の中で「この意見の根拠は？」「データはあるのかな」と、静かに検証していませんか。自分の意見を言う前に、一度完璧に整理したくなって、気づけば議論が次に進んでいる。メモは誰よりも正確に取れているのに、「発言が少なかった」という評価になりそうで不安になる。そんな葛藤を、きっと抱えたことがあるはずです。"}, {"label": "向いている役割", "text": "書記（根拠チェック担当）。"}, {"label": "自然にできる立ち回り", "text": "議論の要点を正確に記録する、意見の根拠やデータの妥当性を確認する、論理の矛盾を指摘する。"}, {"label": "評価されやすいポイント", "text": "正確さ、論理的な視点、議論の質を支える冷静さ。"}, {"label": "やりすぎると逆効果になる行動", "text": "記録に集中して発言しない、細部の正確さにこだわって議論を止める。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "一つのことに集中できる静かな環境で、じっくり取り組める仕事。そんな条件が整っているとき、あなたは驚くほど高い成果を出します。逆に、頻繁に電話や声掛けで集中が途切れたり、次々と新しい仕事が降ってきて優先順位が変わったりする環境では、持ち味の「深さ」が発揮できず、本来の実力の半分も出せなくなる。静かに積み上げられる環境があるかどうかが、あなたの成果を大きく変えます。"}, {"label": "活躍しやすいポジション", "text": "専門知識で組織を支える専門職・アナリスト。担当範囲が明確で、深く掘り下げられる仕事で真価を発揮します。"}, {"label": "組織の中で担いやすい役割", "text": "専門分野の第一人者、品質や数字のチェック役、ナレッジの蓄積役。"}, {"label": "目指しやすいキャリア", "text": "公認会計士・税理士・弁理士などの士業、データアナリスト、設計・品質エンジニア、金融アナリスト、研究員、翻訳・編集の専門職。"}, {"label": "特徴を活かした未来像", "text": "一つの分野を10年以上極め、社内外から「この分野ならこの人に聞けば間違いない」と頼られる専門家になっている。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "自分の仕事に誇りがあるぶん、他の人の雑な仕事を見ると、心の中で「もっとちゃんとやれば」と思ってしまうことはありませんか。口には出さなくても、その気持ちは態度や表情に少し出て、周りが距離を感じていることもある。本当はみんなと上手くやりたいのに、その方法がわからず、一人の時間に逃げ込んでしまう。そんな不器用さが、あなたにはあるのではないでしょうか。"}, {"label": "強みが裏目に出るパターン", "text": "完璧を求めすぎて納期に遅れる、専門外への関心が薄く視野が狭くなる。"}, {"label": "人間関係で気をつけること", "text": "自分から話しかけないと「近寄りがたい」と思われやすい。小さな雑談や挨拶を大切に。"}, {"label": "チームで働く際の注意点", "text": "自分の分析結果を相手にわかる言葉で伝え、チームの意思決定に活かしてもらう。"}, {"label": "意思決定のクセ", "text": "情報を集めすぎて決められない。「この情報が揃ったら決める」と条件を先に決める。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "探す", "text": "志望分野の展示会や技術イベントを1つ探して、来場登録する。"}, {"label": "聞く", "text": "出展している技術者に、「担当領域をどう深めたか」「取った資格と取得にかかった期間」「入社後に担当が固まるまでの期間」を聞く。"}, {"label": "照らす", "text": "聞いた資格や期間を、「今日からできること」で開いた募集要項と照らし合わせる。"}, {"label": "伸ばしたいこと", "items": ["専門分野の資格・知識（簿記、統計検定、TOEICなど）", "自分の考えを簡潔に伝えるコミュニケーション力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、ESの一文一文を何度も見直して、提出ボタンを押す直前まで手を入れていませんか。企業研究も、他の人よりずっと深く調べているのに、「まだ足りない気がする」と不安になる。面接では、準備した答えは完璧なのに、想定外の質問をされると一瞬固まってしまう。その経験があるなら、あなたの準備力は十分で、足りないのは「自信」だけです。"}, {"label": "企業選びのポイント", "text": "総合職のジョブローテーションで専門が定まらないリスクがある。専門性を伸ばせるかを必ず確認する。"}, {"label": "面接で強みを伝えるには", "text": "「〇〇を深く調べて分析し、△の精度で□を完成させた」と、深さと正確さを具体的に示す。"}, {"label": "自己PRで気をつけること", "text": "準備しすぎて棒読みにならないよう、要点だけ覚えて自分の言葉で話す。強みが「正確さ」なら、弱みは「完璧を求めて時間がかかること」と裏表にする。"}, {"label": "適性検査での傾向", "text": "内省性・慎重性・持続性が高く、社会的内向性も高めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["配属・職種の決まり方と、専門職コースの有無を確認したか", "資格取得支援や専門研修があるか調べたか", "一人で集中できる環境（業務の進め方・オフィス環境）か確認したか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "成果物の質で評価される環境にいると、あなたは余計なアピールをしなくても、自然と認められていきます。静かなオフィスで集中して取り組める時間があり、専門性を深めるための勉強を応援してくれる会社なら、10年後には誰にも真似できない存在になっているはずです。逆に、営業的な社交や、頻繁な飲み会が重視される職場では、本来の実力以前に消耗してしまいます。"}, {"label": "相性の良い業界の例", "text": "会計・監査法人、特許事務所、メーカー（設計・品質・研究）、金融（リスク管理・アナリスト）、IT（データ分析）、出版・翻訳。"}, {"label": "相性の良い職種の例", "text": "経理・財務、データアナリスト、設計エンジニア、品質保証、士業、研究員。"}, {"label": "活躍しやすい会社の特徴", "text": "専門性が評価される、職務範囲が明確、腰を据えて長く働ける、品質や正確さを重視する文化。"}, {"label": "ミスマッチになりやすい環境", "text": "スピードとノリ重視、頻繁な異動、飛び込み営業など対人中心の仕事、役割が曖昧な職場。"}, {"label": "このタイプに合いやすい理由", "text": "熟考（D）で深く分析し、安定（S）の環境で着実に専門性を積み上げ、独立（I）で集中して仕事に向き合え、自己実現（G）として「その道のプロ」になれるからです。キャリアアンカーでは、専門・職能別能力と自律・独立、保障・安定が重なる傾向です。"}]}], "DSIP": [{"id": "result-strengths", "title": "あなたの強み", "rows": [{"label": "一言でいうと", "text": "目立たなくても、同じ質で続けられる人。"}, {"label": "このタイプの特徴", "text": "あなたは、誰も見ていない場所でも、やるべきことを同じ質で続けられる人です。ルールや約束を軽く扱わず、「一度決めたことは守る」という姿勢が、長い時間をかけて周りの信頼を静かに積み上げています。派手な成果ではなく、何年もブレずに続けてきた結果として、気づけば「あの人に任せておけば間違いない」と言われる。それがあなたの本当の価値です。"}, {"label": "代表的な強み", "text": "誠実さ、深く考える力、ぶれない価値観、地道に続ける力、専門性を磨いて役立てようとする姿勢。"}, {"label": "力が発揮される場面", "text": "長期的な調査や研究、専門知識が求められる業務、ルールや倫理が重んじられる仕事、一人で集中して質を高める作業。"}, {"label": "他タイプと異なる特徴", "text": "目立たなくても、自分の専門性で社会の土台を支える点。信頼は「派手な成果」ではなく「長年のぶれなさ」で築かれます。"}]}, {"id": "result-weaknesses", "title": "あなたの弱み・苦手なこと", "rows": [{"label": "一言でいうと", "text": "頑張りを伝えるのが苦手で、評価されにくい。"}, {"label": "このタイプの特徴", "text": "自分の頑張りや考えを、わざわざ人に伝える必要はないと思っていませんか。「見ている人は見ているはず」と思いながらも、実際には誰にも伝わっていなくて、静かに悔しい気持ちを抱えたことがあるはずです。また、変化の多い環境や初対面の人が多い場面では、表面上は平静でも、内側ではかなり気を張っている。帰宅した後、ぐったり疲れてしまうのは、そのせいかもしれません。影の部分（普段あまり使わない側）は、自分を前に出して語ること、そしてその場の勢いで動くことです。"}, {"label": "つまずきやすいこと", "text": "自分から発信するのが苦手で、頑張りが伝わりにくい。変化に対して慎重で、新しい環境に慣れるまで時間がかかる。"}, {"label": "力が発揮される場面", "text": "自己PRやGDなど自分を見せる選考、急な環境の変化、競争や売り込みを求められる場面。"}, {"label": "弱みをカバーする方法", "text": "成果を小さく区切って共有する習慣をつける、信頼できる人に自分の仕事を見てもらい言葉にしてもらう。"}]}, {"id": "result-gd", "title": "グループディスカッションでの役割", "rows": [{"label": "このタイプの特徴", "text": "GDで議論が盛り上がる中、あなたは「この案、後で困ることはないかな」「前提は共有できているかな」と、静かに全体を見渡していませんか。発言のタイミングを計っているうちに、議論が次へ進んでしまい、「あれを言えばよかった」と後悔する。それでも、あなたの一言で議論の抜け漏れが埋まった経験は、きっとあるはずです。静かな視点が、実はチームの安心材料になっています。"}, {"label": "向いている役割", "text": "書記（論点の確認役）。"}, {"label": "自然にできる立ち回り", "text": "議論の前提や条件を確認する、抜けている視点を指摘する、全員が納得できる着地点を探す。"}, {"label": "評価されやすいポイント", "text": "誠実さ、冷静な視点、結論の質を高める確認力。"}, {"label": "やりすぎると逆効果になる行動", "text": "慎重になりすぎて発言のタイミングを逃す、細かな指摘ばかりで議論が進まなくなる。"}]}, {"id": "result-career", "title": "あなたに合った立ち回り・キャリア", "rows": [{"label": "このタイプの特徴", "text": "役割が明確で、自分の専門性を信頼して任せてもらえる環境。そんな場所で、あなたは静かに、でも確実に力を発揮します。逆に、毎回言うことが変わる上司や、成果よりも「声の大きさ」が評価される職場では、自分の価値観とのズレを感じて、少しずつ心が疲れていく。社会に必要とされる仕事を、地道に長く続けられることが、あなたにとっての最高の働き方です。"}, {"label": "活躍しやすいポジション", "text": "専門性を活かして社会の仕組みを支える専門職。役割と責任が明確で、長く腰を据えられる場所で力を発揮します。"}, {"label": "組織の中で担いやすい役割", "text": "専門領域の担当者、品質・倫理・安全のチェック役、長期プロジェクトの要。"}, {"label": "目指しやすいキャリア", "text": "公務員（専門職）、研究員、医療・薬学系の専門職、図書館司書や学芸員、環境・衛生分野の技術者、監査・法務の専門家。"}, {"label": "特徴を活かした未来像", "text": "長年積み上げた専門性で、社会のルールや仕組みを静かに支え、「この人の判断なら間違いない」と信頼される存在になっている。"}]}, {"id": "result-cautions", "title": "このタイプが注意すべきこと", "rows": [{"label": "このタイプの特徴", "text": "自分の信念を大切にするあまり、周りの変化に「でも、本当にそれでいいのかな」と一歩引いてしまうことはありませんか。慎重さは大切だけれど、気づけば周りが先に進んでいて、取り残された気持ちになる。「自分は間違っていないはず」と思いつつ、少し寂しさも感じる。その複雑な気持ちを、誰かに話せたら、きっと少し楽になるはずです。"}, {"label": "強みが裏目に出るパターン", "text": "信念が強いぶん、頑固に見られて新しい提案を受け入れにくくなる。"}, {"label": "人間関係で気をつけること", "text": "言葉にしないと意図が伝わらない。感謝や考えを短くても言葉にする。"}, {"label": "チームで働く際の注意点", "text": "一人で完結しようとせず、途中経過を共有して、周りが安心できる状態をつくる。"}, {"label": "意思決定のクセ", "text": "変化を避けて現状維持を選びがち。小さな変化から試して慣らしていく。"}]}, {"id": "result-actions", "title": "今からすべき行動", "rows": [{"label": "選ぶ", "text": "志望する会社や地域で、長く続いている取り組みを1つ選び、担当者に取材をお願いする（メール・電話・OB・OG経由）。"}, {"label": "聞く", "text": "「続けるうえで一番大変なこと」「途中で見直した点」「担当者が休むときの体制」の3つを聞く。"}, {"label": "使う", "text": "聞いた内容を、「続けたことが誰の役に立ったか」の事例として、ガクチカに書き足す。"}, {"label": "伸ばしたいこと", "items": ["専門分野の資格・知識", "自分の仕事の価値を言葉で伝える力"]}]}, {"id": "result-jobhunt", "title": "就活での注意点", "rows": [{"label": "このタイプの特徴", "text": "就活中のあなたは、「自分をアピールする」という行為そのものに、少し抵抗を感じていませんか。周りが堂々と話す姿を見て、「あんなふうに言えない」と落ち込む。けれど、あなたが積み重ねてきた経験や誠実さは、本物です。面接の場で緊張して実力の半分も出せなかった、という悔しさは、準備を真面目にしてきた人だけが味わう感覚です。"}, {"label": "企業選びのポイント", "text": "安定性の中身（仕事内容・異動・勤務形態）を確認する。社会的意義だけでなく、自分の専門性が活きるかも同じ重さで見る。"}, {"label": "面接で強みを伝えるには", "text": "「〇〇の課題に対して地道に△を続け、□という成果につなげた」と、継続と結果で語る。"}, {"label": "自己PRで気をつけること", "text": "控えめになりすぎず、「自分が担った役割」を主語にして話す。強みが「誠実さ」なら、弱みは「自分から発信するのが苦手なこと」と裏表にして、改善している行動を添える。"}, {"label": "適性検査での傾向", "text": "内省性・慎重性・持続性が高く、社会的内向性や回避性も高めに出やすい傾向。"}, {"label": "企業選びのチェックポイント", "items": ["その仕事が社会の「どの安心」を支えているか言えるか", "勤務形態や異動の頻度を具体的に確認したか", "専門性を評価し、長く育てる制度があるか調べたか"]}]}, {"id": "result-industry", "title": "あなたに合いやすい業界・企業環境", "rows": [{"label": "このタイプの特徴", "text": "落ち着いた雰囲気で、専門性と誠実さが評価される職場。そんな環境にいると、あなたは焦らず、自分のペースで、長く力を伸ばしていけます。社会の仕組みを支える仕事は、成果が目に見えにくいぶん、その価値をわかってくれる人がいる環境が大切です。逆に、スピードと勢いだけが評価され、頻繁に方針が変わる職場では、持ち味が活かされず、静かに消耗してしまいます。"}, {"label": "相性の良い業界の例", "text": "官公庁・自治体、研究機関、医療・製薬、教育・図書館・博物館、環境・衛生、インフラ、監査・法務系。"}, {"label": "相性の良い職種の例", "text": "専門職、研究職、品質保証、監査・コンプライアンス、技術職、行政職。"}, {"label": "活躍しやすい会社の特徴", "text": "社会的使命が明確、専門性が評価される、長期的に腰を据えて働ける、落ち着いた環境と誠実さを重んじる文化。"}, {"label": "ミスマッチになりやすい環境", "text": "スピードと勢い重視、短期の数字だけを追う、頻繁な異動や環境変化、強い売り込みが求められる営業。"}, {"label": "このタイプに合いやすい理由", "text": "熟考（D）で深く考えて判断し、安定（S）の環境で着実に専門性を積み上げ、独立（I）で集中して仕事に向き合え、社会貢献（P）の想いが専門性という形で社会に役立つからです。キャリアアンカーでは、奉仕・社会貢献と保障・安定、専門・職能別能力が重なる傾向です。"}]}]};
function buildResultGuidance(index,selected){return importedGuidance[resultProfiles[index].code];}
